-- ✅ دالة تقطيع CSV بسيطة
local function N5LA_SplitCSVLine(line)
    local cols = {}
    local current = ""
    for i = 1, #line do
        local c = line:sub(i, i)
        if c == "," then
            table.insert(cols, current)
            current = ""
        else
            current = current .. c
        end
    end
    table.insert(cols, current)
    for i = 1, #cols do
        cols[i] = cols[i]:gsub("^%s+", ""):gsub("%s+$", ""):gsub('"', '')
    end
    return cols
end

