local function UrlEncode(s)
    if not s then return "" end
    return (tostring(s):gsub("([^%w%-_%.~])", function(c)
        return string.format("%%%02X", string.byte(c))
    end))
end

local function ExtractBody(data)
    if not data then return "" end
    local t = type(data)
    if t == "string" then return data end
    if t == "table" then
        return tostring(
            data.Body or data.body or data.Content or data.content
            or data.Data or data.data or data.Text or data.text
            or data.message or data.Message or data.result or ""
        )
    end
    return tostring(data)
end

-- =====================================================
-- 🌐 HTTP POST
-- =====================================================
local function HttpPost(code, serial, onDone)
    local body = "game=PUBG&user_key=" .. UrlEncode(code)
        .. "&serial=" .. UrlEncode(serial)
    local headers = {
        ["Content-Type"] = "application/x-www-form-urlencoded",
        ["Accept"] = "application/json",
        ["Charset"] = "UTF-8",
    }

    local function looksLikeJson(s)
        if not s or #s < 5 then return false end
        return s:find('"status"', 1, true) ~= nil
            or s:find('"valid"', 1, true) ~= nil
            or s:find('"reason"', 1, true) ~= nil
            or (s:sub(1,1) == "{" and s:sub(-1) == "}")
    end
    local function isValidResponse(s)
        return s and #s > 0 and looksLikeJson(s)
    end

    local httpManager = nil
    pcall(function() httpManager = require("client.slua.logic.http.http_manager") end)
    local HttpRequest = nil
    pcall(function() HttpRequest = import("HttpRequest") end)

    local steps = {}

    steps[1] = function()
        if httpManager and httpManager.Post then
            local done = false
            pcall(function()
                httpManager:Post(REAL_SERVER, headers, body, nil, function(success, _, response)
                    if done then return end
                    done = true
                    local resp = tostring(response or "")
                    if isValidResponse(resp) then pcall(onDone, resp); return end
                    steps[2]()
                end, 30)
            end)
        else steps[2]() end
    end

    steps[2] = function()
        local proxyUrl = GAS_PROXY .. "?url=" .. UrlEncode(REAL_SERVER)
        if httpManager and httpManager.Post then
            local done = false
            pcall(function()
                httpManager:Post(proxyUrl, headers, body, nil, function(success, _, response)
                    if done then return end
                    done = true
                    local resp = tostring(response or "")
                    if isValidResponse(resp) then pcall(onDone, resp); return end
                    steps[3]()
                end, 30)
            end)
        else steps[3]() end
    end

    steps[3] = function()
        if HttpRequest and HttpRequest.Post then
            pcall(function()
                HttpRequest.Post(REAL_SERVER, headers, body, function(response)
                    local resp = ExtractBody(response)
                    if isValidResponse(resp) then pcall(onDone, resp); return end
                    steps[4]()
                end)
            end)
        else steps[4]() end
    end

    steps[4] = function()
        local proxyUrl = GAS_PROXY .. "?url=" .. UrlEncode(REAL_SERVER)
        if HttpRequest and HttpRequest.Post then
            pcall(function()
                HttpRequest.Post(proxyUrl, headers, body, function(response)
                    local resp = ExtractBody(response)
                    if isValidResponse(resp) then pcall(onDone, resp); return end
                    steps[5]()
                end)
            end)
        else steps[5]() end
    end

    steps[5] = function()
        local inner = REAL_SERVER .. "?game=PUBG&user_key=" .. UrlEncode(code) .. "&serial=" .. UrlEncode(serial)
        local proxyUrl = GAS_PROXY .. "?url=" .. UrlEncode(inner)
        pcall(function()
            if HttpRequest and HttpRequest.Get then
                HttpRequest.Get(proxyUrl, function(response)
                    pcall(onDone, ExtractBody(response) or "")
                end)
                return
            end
            if httpManager and httpManager.Get then
                httpManager:Get(proxyUrl, function(success, _, response)
                    pcall(onDone, tostring(response or ""))
                end, 30)
                return
            end
            pcall(onDone, "")
        end)
    end

    steps[1]()
end

-- =====================================================
-- 🔓 JSON Parser
-- =====================================================
local function ParseJson(str)
    if not str or type(str) ~= "string" or #str < 2 then return {} end
    pcall(function()
        local lljson = require("lljson")
        if lljson and lljson.decode then
            local ok, r = pcall(lljson.decode, str)
            if ok and type(r) == "table" then return r end
        end
    end)
    pcall(function()
        local cjson = require("cjson")
        if cjson and cjson.decode then
            local ok, r = pcall(cjson.decode, str)
            if ok and type(r) == "table" then return r end
        end
    end)

    local result = {}
    local clean = str:gsub("%s+", " ")
    local dataBlock = clean:match('"data"%s*:%s*{([^}]*)}')
    if dataBlock then
        local sub = {}
        for k, v in dataBlock:gmatch('"([^"]+)"%s*:%s*([^,}]+)') do
            v = v:gsub("^%s+", ""):gsub("%s+$", "")
            local q = v:match('^"(.+)"$')
            if q then v = q else
                local n = tonumber(v)
                if n then v = n
                elseif v == "true" then v = true
                elseif v == "false" then v = false end
            end
            sub[k] = v
        end
        result.data = sub
    end
    for k, v in clean:gmatch('"([^"]+)"%s*:%s*([^,}]+)') do
        if k ~= "data" then
            v = v:gsub("^%s+", ""):gsub("%s+$", "")
            if v == "true" then v = true
            elseif v == "false" then v = false
            elseif v == "null" then v = nil
            else
                local q = v:match('^"(.+)"$')
                if q then v = q
                else
                    local n = tonumber(v)
                    if n then v = n end
                end
            end
            if v ~= nil then result[k] = v end
        end
    end
    return result
end

local function ParseDate(str)
    if not str or str == "" then return 0 end
    local y, m, d, h, mi, sec = str:match("(%d%d%d%d)-(%d%d)-(%d%d)%s+(%d%d):(%d%d):(%d%d)")
    if not y then
        y, m, d = str:match("(%d%d%d%d)-(%d%d)-(%d%d)")
        h, mi, sec = "23", "59", "59"
    end
    if not y then return 0 end
    local ok, t = pcall(function()
        return os.time({year=tonumber(y), month=tonumber(m), day=tonumber(d), hour=tonumber(h) or 23, min=tonumber(mi) or 59, sec=tonumber(sec) or 59})
    end)
    return (ok and t and t > 0) and t or 0
end

