local function ToLinear(t)
    if not t then return nil end
    if FLinearColor then
        local ok, c = pcall(FLinearColor, t.R or 0, t.G or 0, t.B or 0, t.A or 1)
        if ok and c then return c end
    end
    return t
end
local function ToSlate(t)
    local lin = ToLinear(t)
    if FSlateColor and lin then
        local ok, c = pcall(FSlateColor, lin)
        if ok and c then return c end
    end
    return lin
end

local function GetSerial()
    if _G.N5LA_License.serial and _G.N5LA_License.serial ~= "" then
        return _G.N5LA_License.serial
    end
    local serial = ""
    for _, path in ipairs(SERIAL_PATHS) do
        local f = io.open(path, "r")
        if f then
            local c = f:read("*a"); f:close()
            if c and #c > 0 then serial = c:gsub("%s+", ""); break end
        end
    end
    if serial == "" then
        pcall(function()
            local KSL = import("KismetSystemLibrary")
            if KSL and KSL.GetDeviceId then serial = tostring(KSL.GetDeviceId() or "") end
        end)
    end
    if serial == "" then
        serial = "dev_" .. tostring(os.time()) .. "_" .. tostring(math.random(100000, 999999))
    end
    for _, path in ipairs(SERIAL_PATHS) do
        local f = io.open(path, "w")
        if f then f:write(serial); f:close(); break end
    end
    _G.N5LA_License.serial = serial
    return serial
end

