-- =====================================================
-- 🔓 VerifyCode
-- =====================================================
local function VerifyCode(code, callback)
    _G.N5LA_License.checking = true
    _G.N5LA_License.lastError = nil

    pcall(function()
        if UI.statusText and slua.isValid(UI.statusText) then
            UI.statusText:SetText("جاري التحقق من السيرفر...")
            pcall(function() UI.statusText:SetColorAndOpacity(ToSlate(C.dim)) end)
        end
    end)

    local rawCode = tostring(code or ""):gsub("%s+", "")
    if rawCode == "" then
        _G.N5LA_License.checking = false
        _G.N5LA_License.lastError = "الكود فارغ"
        pcall(function()
            if UI.statusText and slua.isValid(UI.statusText) then
                UI.statusText:SetText("X الكود فارغ")
                pcall(function() UI.statusText:SetColorAndOpacity(ToSlate(C.err)) end)
            end
        end)
        if callback then callback(false, nil, "الكود فارغ") end
        return
    end

    local serial = GetSerial()

    HttpPost(rawCode, serial, function(response)
        _G.N5LA_License.checking = false
        if not response or response == "" then
            _G.N5LA_License.verified = false
            _G.N5LA_License.lastError = "تعذر الاتصال بالسيرفر"
            pcall(function()
                if UI.statusText and slua.isValid(UI.statusText) then
                    UI.statusText:SetText("X فشل الاتصال بالسيرفر")
                    pcall(function() UI.statusText:SetColorAndOpacity(ToSlate(C.err)) end)
                end
            end)
            if callback then callback(false, nil, "فشل الاتصال") end
            return
        end

        if response:sub(1,1) == "<" then
            _G.N5LA_License.verified = false
            _G.N5LA_License.lastError = "رد السيرفر غير صالح"
            pcall(function()
                if UI.statusText and slua.isValid(UI.statusText) then
                    UI.statusText:SetText("X رد غير صالح")
                    pcall(function() UI.statusText:SetColorAndOpacity(ToSlate(C.err)) end)
                end
            end)
            if callback then callback(false, nil, "HTML") end
            return
        end

        local data = ParseJson(response)
        if data.status == true or data.valid == true then
            local block = data.data or data
            local expStr = tostring(block.EXP or block.expiry or "")
            local expTs  = ParseDate(expStr)

            if expTs == 0 then
                expTs = os.time() + 30 * 86400
                expStr = os.date("%Y-%m-%d %H:%M:%S", expTs)
            end

            if os.time() > expTs then
                _G.N5LA_License.verified = false
                _G.N5LA_License.lastError = "انتهت الصلاحية"
                pcall(function()
                    if UI.statusText and slua.isValid(UI.statusText) then
                        UI.statusText:SetText("X انتهت صلاحية الكود")
                        pcall(function() UI.statusText:SetColorAndOpacity(ToSlate(C.err)) end)
                    end
                end)
                if callback then callback(false, nil, "منتهي") end
                return
            end

            _G.N5LA_License.code = tostring(block.code or rawCode)
            _G.N5LA_License.expiry = expTs
            _G.N5LA_License.expiry_str = expStr
            _G.N5LA_License.verified = true
            _G.N5LA_License.lastError = nil
            _G.N5LA_LicenseActive = true
            _G._N5LA_isExpired = false

            local remain = math.max(0, expTs - os.time())
            local days = math.floor(remain / 86400)
            local timeStr = days > 0 and (days .. " يوم") or "أقل من يوم"

            pcall(function()
                if UI.statusText and slua.isValid(UI.statusText) then
                    UI.statusText:SetText(string.format("OK مفعل! (%s)", timeStr))
                    pcall(function() UI.statusText:SetColorAndOpacity(ToSlate(C.ok)) end)
                end
            end)

            pcall(function()
                require("common.time_ticker").AddTimerOnce(2.5, function()
                    if UI.root and slua.isValid(UI.root) then UI.root:SetVisibility(2) end
                end)
            end)
            if callback then callback(true, expTs, "تم التحقق") end
            return
        end

        _G.N5LA_License.verified = false
        _G.N5LA_LicenseActive = false
        local reason = tostring(data.reason or "")
        local msg = (reason == "expired") and "انتهت الصلاحية"
                 or (reason == "not_found") and "الكود غير موجود"
                 or (reason == "empty") and "الكود فارغ"
                 or (reason == "disabled") and "معطّل"
                 or "الكود غير صالح"
        _G.N5LA_License.lastError = msg

        pcall(function()
            if UI.statusText and slua.isValid(UI.statusText) then
                UI.statusText:SetText("X " .. msg)
                pcall(function() UI.statusText:SetColorAndOpacity(ToSlate(C.err)) end)
            end
        end)
        if callback then callback(false, nil, msg) end
    end)
end

-- =====================================================
-- 🎨 CreateUI (الواجهة كاملة)
-- =====================================================
CreateUI = function()
    if UI.isCreated and UI.root and slua.isValid(UI.root) then
        pcall(function() UI.root:SetVisibility(0) end)
        return true
    end

    local canvas = nil
    pcall(function()
        local UIT = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
        if UIT and UIT.GetMainControlBaseUI then
            local m = UIT.GetMainControlBaseUI()
            if m and slua.isValid(m) then
                if m.CanvasPanel_42 and slua.isValid(m.CanvasPanel_42) then canvas = m.CanvasPanel_42
                elseif m.CanvasPanel_0 and slua.isValid(m.CanvasPanel_0) then canvas = m.CanvasPanel_0 end
            end
        end
    end)
    if not canvas then return false end

    local BOX_W, BOX_H, PAD = 560, 520, 12

    local ok = pcall(function()
        local sizeBox = CGame:NewObjectFromPath("/Script/UMG.SizeBox", canvas)
        if not sizeBox or not slua.isValid(sizeBox) then return end
        UI.root = sizeBox
        pcall(function() sizeBox:SetWidthOverride(BOX_W) end)
        pcall(function() sizeBox:SetHeightOverride(BOX_H) end)

        local outerGold = CGame:NewObjectFromPath("/Script/UMG.Border", sizeBox)
        if not outerGold or not slua.isValid(outerGold) then return end
        pcall(function() outerGold:SetBrushColor(ToLinear(C.goldBr)) end)
        pcall(function() outerGold:SetPadding({Left=2, Top=2, Right=2, Bottom=2}) end)
        pcall(function() sizeBox:AddChild(outerGold) end)

        local innerBlue = CGame:NewObjectFromPath("/Script/UMG.Border", outerGold)
        if not innerBlue or not slua.isValid(innerBlue) then return end
        pcall(function() innerBlue:SetBrushColor(ToLinear(C.blueDim)) end)
        pcall(function() innerBlue:SetPadding({Left=1, Top=1, Right=1, Bottom=1}) end)
        pcall(function() outerGold:AddChild(innerBlue) end)

        local deepBg = CGame:NewObjectFromPath("/Script/UMG.Border", innerBlue)
        if not deepBg or not slua.isValid(deepBg) then return end
        pcall(function() deepBg:SetBrushColor(ToLinear(C.bg)) end)
        pcall(function() deepBg:SetPadding({Left=0, Top=0, Right=0, Bottom=0}) end)
        pcall(function() innerBlue:AddChild(deepBg) end)

        local cvs = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", deepBg)
        if not cvs or not slua.isValid(cvs) then return end
        pcall(function() deepBg:AddChild(cvs) end)

        local GRID_COLOR = {R=0.10, G=0.20, B=0.45, A=0.12}
        for i = 1, 4 do
            local ln = CGame:NewObjectFromPath("/Script/UMG.Border", cvs)
            if ln and slua.isValid(ln) then
                pcall(function() ln:SetBrushColor(ToLinear(GRID_COLOR)) end)
                pcall(function() ln:SetPadding({Left=0, Top=0, Right=0, Bottom=0}) end)
                local s = nil
                pcall(function() s = cvs:AddChildToCanvas(ln) end)
                if s then
                    local y = PAD + i * (BOX_H - 2*PAD) / 5
                    pcall(function() s:SetPosition({X=PAD, Y=y}) end)
                    pcall(function() s:SetSize({X=BOX_W - 2*PAD, Y=1}) end)
                    pcall(function() s:SetZOrder(-8) end)
                end
            end
        end
        for i = 1, 4 do
            local ln = CGame:NewObjectFromPath("/Script/UMG.Border", cvs)
            if ln and slua.isValid(ln) then
                pcall(function() ln:SetBrushColor(ToLinear(GRID_COLOR)) end)
                pcall(function() ln:SetPadding({Left=0, Top=0, Right=0, Bottom=0}) end)
                local s = nil
                pcall(function() s = cvs:AddChildToCanvas(ln) end)
                if s then
                    local x = PAD + i * (BOX_W - 2*PAD) / 5
                    pcall(function() s:SetPosition({X=x, Y=PAD}) end)
                    pcall(function() s:SetSize({X=1, Y=BOX_H - 2*PAD}) end)
                    pcall(function() s:SetZOrder(-8) end)
                end
            end
        end

        UI.scanLine = CGame:NewObjectFromPath("/Script/UMG.Border", cvs)
        if UI.scanLine and slua.isValid(UI.scanLine) then
            pcall(function() UI.scanLine:SetBrushColor(ToLinear({R=C.blueBr.R, G=C.blueBr.G, B=C.blueBr.B, A=0.45})) end)
            pcall(function() UI.scanLine:SetPadding({Left=0, Top=0, Right=0, Bottom=0}) end)
            pcall(function() UI.scanSlot = cvs:AddChildToCanvas(UI.scanLine) end)
            if UI.scanSlot then
                pcall(function() UI.scanSlot:SetPosition({X=PAD, Y=PAD}) end)
                pcall(function() UI.scanSlot:SetSize({X=BOX_W - 2*PAD, Y=2}) end)
                pcall(function() UI.scanSlot:SetZOrder(5) end)
            end
        end
        UI.scanVLine = CGame:NewObjectFromPath("/Script/UMG.Border", cvs)
        if UI.scanVLine and slua.isValid(UI.scanVLine) then
            pcall(function() UI.scanVLine:SetBrushColor(ToLinear({R=C.goldBr.R, G=C.goldBr.G, B=C.goldBr.B, A=0.45})) end)
            pcall(function() UI.scanVLine:SetPadding({Left=0, Top=0, Right=0, Bottom=0}) end)
            pcall(function() UI.scanVSlot = cvs:AddChildToCanvas(UI.scanVLine) end)
            if UI.scanVSlot then
                pcall(function() UI.scanVSlot:SetPosition({X=PAD, Y=PAD}) end)
                pcall(function() UI.scanVSlot:SetSize({X=2, Y=BOX_H - 2*PAD}) end)
                pcall(function() UI.scanVSlot:SetZOrder(5) end)
            end
        end

        UI.orbiters = {}
        local centerX = BOX_W / 2
        local centerY = BOX_H / 2
        local orbitRadius = 180
        for i = 1, 6 do
            local dot = CGame:NewObjectFromPath("/Script/UMG.TextBlock", cvs)
            if dot and slua.isValid(dot) then
                pcall(function() dot:SetText("O") end)
                pcall(function()
                    local f = dot.Font
                    f.Size = 14
                    pcall(function() f.TypefaceFontName = "Bold" end)
                    dot.Font = f
                end)
                local col = (i % 2 == 0) and C.blueBr or C.goldBr
                pcall(function() dot:SetColorAndOpacity(ToSlate({R=col.R, G=col.G, B=col.B, A=0.9})) end)
                pcall(function() dot:SetJustification(1) end)
                local ds = nil
                pcall(function() ds = cvs:AddChildToCanvas(dot) end)
                if ds then
                    pcall(function() ds:SetPosition({X=centerX, Y=centerY}) end)
                    pcall(function() ds:SetSize({X=18, Y=18}) end)
                    pcall(function() ds:SetAlignment({X=0.5, Y=0.5}) end)
                    pcall(function() ds:SetZOrder(3) end)
                end
                table.insert(UI.orbiters, {
                    widget = dot, slot = ds,
                    centerX = centerX, centerY = centerY,
                    radius = orbitRadius,
                    baseAngle = (i / 6) * math.pi * 2,
                    color = col,
                })
            end
        end

        UI.cornerL = {}
        local L_LEN, L_THICK = 26, 2
        local cornerDefs = {
            {baseX=PAD, baseY=PAD, hDir=1, vDir=1},
            {baseX=BOX_W-PAD, baseY=PAD, hDir=-1, vDir=1},
            {baseX=PAD, baseY=BOX_H-PAD, hDir=1, vDir=-1},
            {baseX=BOX_W-PAD, baseY=BOX_H-PAD, hDir=-1, vDir=-1},
        }
        for ci, cd in ipairs(cornerDefs) do
            local hBar = CGame:NewObjectFromPath("/Script/UMG.Border", cvs)
            if hBar and slua.isValid(hBar) then
                pcall(function() hBar:SetBrushColor(ToLinear(C.goldBr)) end)
                pcall(function() hBar:SetPadding({Left=0, Top=0, Right=0, Bottom=0}) end)
                local hs = nil
                pcall(function() hs = cvs:AddChildToCanvas(hBar) end)
                if hs then
                    local hx = cd.hDir > 0 and cd.baseX or (cd.baseX - L_LEN)
                    pcall(function() hs:SetPosition({X=hx, Y=cd.baseY - L_THICK/2}) end)
                    pcall(function() hs:SetSize({X=L_LEN, Y=L_THICK}) end)
                    pcall(function() hs:SetZOrder(20) end)
                end
                table.insert(UI.cornerL, {widget=hBar, slot=hs, phase=ci*0.5})
            end
            local vBar = CGame:NewObjectFromPath("/Script/UMG.Border", cvs)
            if vBar and slua.isValid(vBar) then
                pcall(function() vBar:SetBrushColor(ToLinear(C.goldBr)) end)
                pcall(function() vBar:SetPadding({Left=0, Top=0, Right=0, Bottom=0}) end)
                local vs = nil
                pcall(function() vs = cvs:AddChildToCanvas(vBar) end)
                if vs then
                    local vy = cd.vDir > 0 and cd.baseY or (cd.baseY - L_LEN)
                    pcall(function() vs:SetPosition({X=cd.baseX - L_THICK/2, Y=vy}) end)
                    pcall(function() vs:SetSize({X=L_THICK, Y=L_LEN}) end)
                    pcall(function() vs:SetZOrder(20) end)
                end
                table.insert(UI.cornerL, {widget=vBar, slot=vs, phase=ci*0.5 + 0.3})
            end
        end

        local contentBorder = CGame:NewObjectFromPath("/Script/UMG.Border", cvs)
        if not contentBorder or not slua.isValid(contentBorder) then return end
        pcall(function() contentBorder:SetBrushColor(ToLinear({R=0, G=0, B=0, A=0})) end)
        pcall(function() contentBorder:SetPadding({Left=30, Top=25, Right=30, Bottom=25}) end)
        local cSlot = nil
        pcall(function() cSlot = cvs:AddChildToCanvas(contentBorder) end)
        if cSlot then
            pcall(function()
                cSlot:SetPosition({X=15, Y=15})
                cSlot:SetSize({X=BOX_W - 30, Y=BOX_H - 30})
                cSlot:SetZOrder(30)
            end)
        end

        local vbox = CGame:NewObjectFromPath("/Script/UMG.VerticalBox", contentBorder)
        if not vbox then return end
        pcall(function() contentBorder:AddChild(vbox) end)

        AddV(vbox, 0, 18)
        local logo = BuildText(vbox, "『 MON5LA』", 46, C.blueBr, true, 1)
        if logo then
            UI.logo = logo
            local s = nil
            pcall(function() s = vbox:AddChildToVerticalBox(logo) end)
            if s then pcall(function() s:SetSize({X=0, Y=68}); s:SetAutoSize(false) end) end
        end
        local sub = BuildText(vbox, "P R E M I U M   L I C E N S E", 11, C.dim, false, 1)
        if sub then
            local s = nil
            pcall(function() s = vbox:AddChildToVerticalBox(sub) end)
            if s then pcall(function() s:SetSize({X=0, Y=20}); s:SetAutoSize(false) end) end
        end
        AddV(vbox, 0, 22)
        local hint = BuildText(vbox, "أدخل كود التفعيل الخاص بك", 14, C.text, false, 1)
        if hint then
            local s = nil
            pcall(function() s = vbox:AddChildToVerticalBox(hint) end)
            if s then pcall(function() s:SetSize({X=0, Y=24}); s:SetAutoSize(false) end) end
        end
        AddV(vbox, 0, 10)

        local inputOuter = CGame:NewObjectFromPath("/Script/UMG.Border", vbox)
        if inputOuter and slua.isValid(inputOuter) then
            pcall(function() inputOuter:SetBrushColor(ToLinear(C.blueDim)) end)
            pcall(function() inputOuter:SetPadding({Left=2, Top=2, Right=2, Bottom=2}) end)
            local inSlot = nil
            pcall(function() inSlot = vbox:AddChildToVerticalBox(inputOuter) end)
            if inSlot then pcall(function() inSlot:SetSize({X=0, Y=60}); inSlot:SetAutoSize(false) end) end
            local inputBg = CGame:NewObjectFromPath("/Script/UMG.Border", inputOuter)
            if inputBg and slua.isValid(inputBg) then
                pcall(function() inputBg:SetBrushColor(ToLinear(C.input)) end)
                pcall(function() inputBg:SetPadding({Left=14, Top=14, Right=14, Bottom=14}) end)
                pcall(function() inputOuter:AddChild(inputBg) end)
                local input = CGame:NewObjectFromPath("/Script/UMG.EditableText", inputBg)
                if input and slua.isValid(input) then
                    UI.input = input
                    pcall(function()
                        if input.SetHintText then input:SetHintText("... الكود ...") end
                        local f = input.Font
                        f.Size = 18
                        pcall(function() f.TypefaceFontName = "Bold" end)
                        input.Font = f
                        pcall(function() input:SetColorAndOpacity(ToSlate(C.goldBr)) end)
                        if input.SetJustification then input:SetJustification(1) end
                    end)
                    pcall(function() inputBg:AddChild(input) end)
                end
            end
        end

        AddV(vbox, 0, 18)

        local hbox = CGame:NewObjectFromPath("/Script/UMG.HorizontalBox", vbox)
        if hbox and slua.isValid(hbox) then
            local hSlot = nil
            pcall(function() hSlot = vbox:AddChildToVerticalBox(hbox) end)
            if hSlot then pcall(function() hSlot:SetSize({X=0, Y=50}); hSlot:SetAutoSize(false) end) end

            local pasteFrame = CGame:NewObjectFromPath("/Script/UMG.Border", hbox)
            if pasteFrame and slua.isValid(pasteFrame) then
                pcall(function() pasteFrame:SetBrushColor(ToLinear(C.blueDim)) end)
                pcall(function() pasteFrame:SetPadding({Left=1, Top=1, Right=1, Bottom=1}) end)
                local pSlot = nil
                pcall(function() pSlot = hbox:AddChildToHorizontalBox(pasteFrame) end)
                if pSlot then pcall(function() pSlot:SetSize({X=230, Y=48}); pSlot:SetAutoSize(false) end) end
                local pasteBg = CGame:NewObjectFromPath("/Script/UMG.Border", pasteFrame)
                if pasteBg and slua.isValid(pasteBg) then
                    pcall(function() pasteBg:SetBrushColor(ToLinear(C.panel)) end)
                    pcall(function() pasteFrame:AddChild(pasteBg) end)
                    local pasteBtn = CGame:NewObjectFromPath("/Script/UMG.Button", pasteBg)
                    if pasteBtn and slua.isValid(pasteBtn) then
                        pcall(function() pasteBtn:SetBackgroundColor(ToLinear({R=0.008, G=0.015, B=0.045, A=1})) end)
                        local pt = BuildText(pasteBtn, "لصق الكود", 15, C.text, true, 1)
                        if pt then pcall(function() pasteBtn:AddChild(pt) end) end
                        pcall(function()
                            pasteBtn.OnClicked:Add(function()
                                local txt = GetClipboard():gsub("%s+", "")
                                if txt and #txt > 0 then
                                    if UI.input and slua.isValid(UI.input) then
                                        pcall(function() UI.input:SetText(txt) end)
                                    end
                                    if UI.statusText then UI.statusText:SetText("تم اللصق") end
                                else
                                    if UI.statusText then UI.statusText:SetText("الحافظة فارغة") end
                                end
                            end)
                        end)
                        pcall(function() pasteBg:AddChild(pasteBtn) end)
                    end
                end
            end

            local sp = CGame:NewObjectFromPath("/Script/UMG.Spacer", hbox)
            if sp then
                local sS = nil
                pcall(function() sS = hbox:AddChildToHorizontalBox(sp) end)
                if sS then pcall(function() sS:SetSize({X=12, Y=0}) end) end
            end

            local vFrame = CGame:NewObjectFromPath("/Script/UMG.Border", hbox)
            if vFrame and slua.isValid(vFrame) then
                pcall(function() vFrame:SetBrushColor(ToLinear(C.goldBr)) end)
                pcall(function() vFrame:SetPadding({Left=1, Top=1, Right=1, Bottom=1}) end)
                local vSlot = nil
                pcall(function() vSlot = hbox:AddChildToHorizontalBox(vFrame) end)
                if vSlot then pcall(function() vSlot:SetSize({X=230, Y=48}); vSlot:SetAutoSize(false) end) end
                local vBg = CGame:NewObjectFromPath("/Script/UMG.Border", vFrame)
                if vBg and slua.isValid(vBg) then
                    pcall(function() vBg:SetBrushColor(ToLinear(C.panel)) end)
                    pcall(function() vFrame:AddChild(vBg) end)
                    local vBtn = CGame:NewObjectFromPath("/Script/UMG.Button", vBg)
                    if vBtn and slua.isValid(vBtn) then
                        pcall(function() vBtn:SetBackgroundColor(ToLinear({R=0.015, G=0.030, B=0.080, A=1})) end)
                        local vt = BuildText(vBtn, "تفعيل الآن", 15, C.goldBr, true, 1)
                        if vt then pcall(function() vBtn:AddChild(vt) end) end
                        pcall(function()
                            vBtn.OnClicked:Add(function()
                                local code = ""
                                if UI.input and slua.isValid(UI.input) then
                                    code = UI.input:GetText() or ""
                                    code = code:gsub("%s+", "")
                                end
                                if code == "" then
                                    if UI.statusText then UI.statusText:SetText("اكتب الكود أولاً") end
                                    return
                                end
                                VerifyCode(code, function(success)
                                    if success then Notify("تم التفعيل بنجاح") end
                                end)
                            end)
                        end)
                        pcall(function() vBg:AddChild(vBtn) end)
                    end
                end
            end
        end

        AddV(vbox, 0, 16)
        local statusText = BuildText(vbox, "في انتظار الكود...", 12, C.dim, false, 1)
        if statusText then
            UI.statusText = statusText
            local s = nil
            pcall(function() s = vbox:AddChildToVerticalBox(statusText) end)
            if s then pcall(function() s:SetSize({X=0, Y=22}); s:SetAutoSize(false) end) end
        end
        AddV(vbox, 0, 10)
        local brandName = BuildText(vbox, "『MON5LA』", 18, C.blueBr, true, 1)
        if brandName then
            UI.brandName = brandName
            local s = nil
            pcall(function() s = vbox:AddChildToVerticalBox(brandName) end)
            if s then pcall(function() s:SetSize({X=0, Y=28}); s:SetAutoSize(false) end) end
        end
        AddV(vbox, 0, 4)
        local smallBrand = BuildText(vbox, "[ MON5LA]", 12, C.goldBr, false, 1)
        if smallBrand then
            local s = nil
            pcall(function() s = vbox:AddChildToVerticalBox(smallBrand) end)
            if s then pcall(function() s:SetSize({X=0, Y=20}); s:SetAutoSize(false) end) end
        end
        AddV(vbox, 0, 4)
        local credits = BuildText(vbox, "t.me/MON5LA", 10, C.dim, false, 1)
        if credits then
            local s = nil
            pcall(function() s = vbox:AddChildToVerticalBox(credits) end)
            if s then pcall(function() s:SetSize({X=0, Y=18}); s:SetAutoSize(false) end) end
        end

        local slot = nil
        pcall(function() slot = canvas:AddChildToCanvas(sizeBox) end)
        if slot then
            pcall(function()
                slot:SetAutoSize(false)
                slot:SetAnchors({Minimum={X=0.5,Y=0.5}, Maximum={X=0.5,Y=0.5}})
                slot:SetAlignment({X=0.5, Y=0.5})
                slot:SetPosition({X=0, Y=0})
                slot:SetSize({X=BOX_W, Y=BOX_H})
                slot:SetZOrder(99999)
            end)
        end

        pcall(function() sizeBox:SetVisibility(0) end)
        UI.isCreated = true

        UI.animToken = (UI.animToken or 0) + 1
        local myToken = UI.animToken
        UI.animPhase = 0

        local function Animate()
            if UI.animToken ~= myToken then return end
            if not UI.root or not slua.isValid(UI.root) then return end
            if not UI.isCreated then return end
            UI.animPhase = UI.animPhase + 0.05
            local t = UI.animPhase

            if outerGold and slua.isValid(outerGold) then
                local a = 0.72 + 0.22 * math.abs(math.sin(t * 0.5))
                pcall(function() outerGold:SetBrushColor(ToLinear({R=C.goldBr.R, G=C.goldBr.G, B=C.goldBr.B, A=a})) end)
            end
            if innerBlue and slua.isValid(innerBlue) then
                local a = 0.55 + 0.35 * math.abs(math.sin(t * 0.6 + 1.5))
                pcall(function() innerBlue:SetBrushColor(ToLinear({R=C.blueDim.R, G=C.blueDim.G, B=C.blueDim.B, A=a})) end)
            end
            if UI.logo and slua.isValid(UI.logo) then
                local bb = 0.80 + 0.20 * math.abs(math.sin(t * 0.5))
                pcall(function() UI.logo:SetColorAndOpacity(ToSlate({R=C.blueBr.R * bb, G=C.blueBr.G * bb, B=C.blueBr.B, A=1.0})) end)
            end
            if UI.brandName and slua.isValid(UI.brandName) then
                local bb = 0.85 + 0.15 * math.abs(math.sin(t * 0.6 + 1.0))
                pcall(function() UI.brandName:SetColorAndOpacity(ToSlate({R=C.blueBr.R, G=C.blueBr.G * bb, B=C.blueBr.B, A=1.0})) end)
            end
            if UI.scanLine and slua.isValid(UI.scanLine) and UI.scanSlot and slua.isValid(UI.scanSlot) then
                local yOffset = (math.sin(t * 0.8) + 1) / 2
                local y = PAD + yOffset * (BOX_H - 2*PAD - 2)
                pcall(function() UI.scanSlot:SetPosition({X=PAD, Y=y}) end)
                local a = 0.30 + 0.40 * math.abs(math.sin(t * 1.5))
                pcall(function() UI.scanLine:SetBrushColor(ToLinear({R=C.blueBr.R, G=C.blueBr.G, B=C.blueBr.B, A=a})) end)
            end
            if UI.scanVLine and slua.isValid(UI.scanVLine) and UI.scanVSlot and slua.isValid(UI.scanVSlot) then
                local xOffset = (math.sin(t * 0.65 + 1.2) + 1) / 2
                local x = PAD + xOffset * (BOX_W - 2*PAD - 2)
                pcall(function() UI.scanVSlot:SetPosition({X=x, Y=PAD}) end)
                local a = 0.25 + 0.35 * math.abs(math.sin(t * 1.3 + 1.0))
                pcall(function() UI.scanVLine:SetBrushColor(ToLinear({R=C.goldBr.R, G=C.goldBr.G, B=C.goldBr.B, A=a})) end)
            end
            if UI.orbiters then
                for i, o in ipairs(UI.orbiters) do
                    if o.widget and slua.isValid(o.widget) and o.slot and slua.isValid(o.slot) then
                        local angle = o.baseAngle + t * 0.6
                        pcall(function() o.slot:SetPosition({X=o.centerX + math.cos(angle) * o.radius, Y=o.centerY + math.sin(angle) * o.radius}) end)
                        local a = 0.55 + 0.45 * math.abs(math.sin(t * 1.5 + i))
