local function redirect_packets()
    if not NetUtil or not NetUtil.SendPacket then return end
    if V._p1 then return end
    if NetUtil._v14_redirected then return end
    V._p1 = true
    NetUtil._v14_redirected = true
    
    local original = NetUtil.SendPacket
    
    local cleanable = {
        [_d(114,101,112,111,114,116,95,97,105,109,95,98,111,116)] = true,
        [_d(114,101,112,111,114,116,95,119,97,108,108,95,104,97,99,107)] = true,
        [_d(114,101,112,111,114,116,95,115,112,101,101,100,95,104,97,99,107)] = true,
        [_d(100,101,116,101,99,116,95,99,104,101,97,116)] = true,
        [_d(67,104,101,97,116,68,101,116,101,99,116,105,111,110)] = true,
        [_d(86,105,111,108,97,116,105,111,110,82,101,112,111,114,116)] = true,
        [_d(83,101,99,117,114,105,116,121,86,105,111,108,97,116,105,111,110)] = true,
    }
    
    local fatal = {
        [_d(98,97,110,95,112,108,97,121,101,114)] = true,
        [_d(66,97,110,80,108,97,121,101,114)] = true,
        [_d(75,105,99,107,80,108,97,121,101,114)] = true,
        [_d(78,111,116,105,102,121,66,97,110)] = true,
        [_d(65,112,112,108,121,66,97,110)] = true,
        [_d(66,97,110,78,111,116,105,102,105,99,97,116,105,111,110)] = true,
        [_d(83,117,115,112,101,110,100,80,108,97,121,101,114)] = true,
    }
    
    NetUtil.SendPacket = function(name, ...)
        if type(name) == "string" then
            if fatal[name] then
                V.n2 = V.n2 + 1
                return nil
            end
            if cleanable[name] then
                local args = {...}
                for i = 1, #args do
                    if type(args[i]) == "table" then
                        for k, v in pairs(args[i]) do
                            if type(v) == "number" and v > 100 then
                                args[i][k] = math.random(1, 10)
                            end
                        end
                    end
                end
                return original(name, unpack(args))
            end
        end
        return original(name, ...)
    end
end
