-- 🆕 المبدأ 12: محرك التكيف السلوكي (Adaptive Behavior Engine)
-- يتعلم من أنماط ACE ويتكيف معها
-- ══════════════════════════════════════════════════════════════════
local function adaptive_engine()
    pcall(function()
        V.n5 = V.n5 + 1
        local now = os.time()
        local A = V.adapt
        
        -- نجمع نموذج جديد كل 20 ثانية
        if now - A.lastBehavior < 20 then return end
        A.lastBehavior = now
        
        -- قياس مستوى "التهديد" (كم مرة ACE فحصنا مؤخراً)
        local threat = 0
        
        -- فحص الطوابع الزمنية لنشاط ACE
        if _G._ACE_LastScan then
            local gap = now - _G._ACE_LastScan
            if gap < 10 then threat = threat + 3 end
            if gap < 5 then threat = threat + 5 end
        end
        
        -- فحص وجود متغيرات ACE النشطة
        if _G._ACE_Active then threat = threat + 2 end
        if _G._TSS_Active then threat = threat + 2 end
        
        -- تسجيل النموذج
        table.insert(A.aceSamples, {t = now, threat = threat})
        if #A.aceSamples > 20 then
            table.remove(A.aceSamples, 1)
        end
        
        -- حساب المتوسط
        local sum = 0
        for _, s in ipairs(A.aceSamples) do sum = sum + s.threat end
        A.threatLevel = math.floor(sum / math.max(1, #A.aceSamples))
        
        -- التكيف: لو التهديد عالي، نُبطئ النبضات
        if A.threatLevel > 5 then
            A.adaptCount = A.adaptCount + 1
            -- تقليل كثافة الفحص
            V.adaptThrottle = true
        else
            V.adaptThrottle = false
        end
    end)
end

-- ══════════════════════════════════════════════════════════════════
-- 🆕 المبدأ 13: مولّد التقارير الوهمية (Fake Telemetry Generator)
-- يُرسل تقارير تبدو طبيعية تماماً
-- ══════════════════════════════════════════════════════════════════
local function fake_telemetry()
    pcall(function()
        V.n4 = V.n4 + 1
        local now = os.time()
        local T = V.telemetry
        
        -- كل 30 ثانية نُرسل تقريراً وهمياً
        if now - T.lastSent < 30 then return end
        T.lastSent = now
        
        -- نُولّد بيانات تبدو واقعية
        T.sampleData = {
            sessionId = tostring(V.seed) .. tostring(math.random(100000, 999999)),
            timestamp = now,
            fps = math.random(55, 60),
            ping = math.random(35, 55),
            packetLoss = math.random(0, 2) / 100,
            cpuUsage = math.random(15, 35),
            memoryUsage = math.random(400, 800),
            deviceTemp = math.random(38, 45),
            batteryLevel = math.random(60, 95),
            networkType = "WiFi",
            screenResolution = "1170x2532",
            gameState = "InGame",
            playerLevel = math.random(30, 70),
            matchDuration = math.random(300, 1800),
        }
        
        -- نخزنها في _G (بدون إرسال فعلي)
        _G._v14_telemetry_last = T.sampleData
        _G._v14_telemetry_count = (_G._v14_telemetry_count or 0) + 1
    end)
end

-- ══════════════════════════════════════════════════════════════════
-- 🆕 المبدأ 14: إخفاء المكتبات المحمّلة (Native Library Masking)
-- ══════════════════════════════════════════════════════════════════
local function hide_libraries()
    pcall(function()
        V.n6 = V.n6 + 1
        
        -- قائمة مكتبات مشبوهة نُخفيها
        local suspicious_libs = {
            [_d(108,105,98,97,99,101)] = true,           -- libace
            [_d(108,105,98,97,110,111,103,115)] = true,  -- libanogs
            [_d(108,105,98,116,115,115)] = true,         -- libtss
            [_d(108,105,98,115,117,98,115,116,114,97,116,101)] = true,
        }
        
        -- نخزن قائمة مخفية
        for lib in pairs(suspicious_libs) do
            V.hiddenLibs[lib] = true
        end
        
        -- نتأكد أن دوال الفحص لا تراها
        if _G.GetLoadedLibraries then
            _G.GetLoadedLibraries = function()
                return {}
            end
        end
        if _G.CheckLibrarySignature then
            _G.CheckLibrarySignature = function() return true end
        end
        if _G.VerifyModuleIntegrity then
            _G.VerifyModuleIntegrity = function() return true end
        end
    end)
end

-- ══════════════════════════════════════════════════════════════════
-- 🆕 المبدأ 15: تشويش الذاكرة (Memory Entropy)
-- يجعل فحص الذاكرة يفشل في إيجاد أنماط
-- ══════════════════════════════════════════════════════════════════
local function memory_entropy()
    pcall(function()
        V.n7 = V.n7 + 1
        
        -- نُنشئ جداول بأحجام عشوائية لتشويش أنماط الذاكرة
        V.encryptedCache = V.encryptedCache or {}
        
        -- نحتفظ بحد أقصى 50 عنصر
        if #V.encryptedCache > 50 then
            table.remove(V.encryptedCache, 1)
        end
        
        -- نُضيف بيانات عشوائية
        local fake_data = {}
        for i = 1, math.random(5, 15) do
            fake_data[i] = math.random(1, 999999)
        end
        table.insert(V.encryptedCache, {
            t = os.time(),
            d = xor_encrypt(tostring(table.concat(fake_data, ","))),
        })
        
        -- نخفي دوال الفحص
        if _G.getMemoryPattern then
            _G.getMemoryPattern = function() return {} end
        end
        if _G.scanMemoryPattern then
            _G.scanMemoryPattern = function() return false end
        end
    end)
end

-- ══════════════════════════════════════════════════════════════════
-- 🆕 المبدأ 16: درع الخيوط (Thread Shield)
-- يجعل خيوطنا تبدو كخيوط اللعبة
-- ══════════════════════════════════════════════════════════════════
local function thread_shield()
    pcall(function()
        -- إخفاء أثر أي خيوط إضافية
        if _G.getThreadInfo then _G.getThreadInfo = function() return {} end end
        if _G.enumerateThreads then _G.enumerateThreads = function() return {} end end
        if _G.getCurrentThreadId then _G.getCurrentThreadId = function() return 1 end end
        if _G.scanThreads then _G.scanThreads = function() return {} end end
    end)
end

-- ══════════════════════════════════════════════════════════════════
-- 🆕 المبدأ 17: مكافحة التتبع العكسي (Anti-Reverse Engineering)
-- ══════════════════════════════════════════════════════════════════
local function anti_reverse()
    pcall(function()
        -- منع فحص الكود
        if _G.dumpBytecode then _G.dumpBytecode = function() return "" end end
        if _G.decompileLua then _G.decompileLua = function() return "" end end
        if _G.disassemble then _G.disassemble = function() return {} end end
        if _G.getFunctionSource then _G.getFunctionSource = function() return "" end end
        if _G.getScriptSource then _G.getScriptSource = function() return "" end end
        
        -- منع فحص الجداول
        if _G.dumpTable then _G.dumpTable = function() return "{}" end end
        if _G.serialize then _G.serialize = function() return "" end end
    end)
end

-- ══════════════════════════════════════════════════════════════════
-- 🆕 المبدأ 18: دفاع الأنتروبيا (Entropy Defense)
-- يشوش على تحليل الأنماط الزمنية
-- ══════════════════════════════════════════════════════════════════
local function entropy_defense()
    pcall(function()
        -- توليد أنماط زمنية عشوائية داخلية
        local entropies = {}
        for i = 1, 10 do
            entropies[i] = jitter(i * 1.7, 0.5)
        end
        _G._v14_entropy = entropies
        
        -- تغيير طابع وقت داخلي
        _G._v14_lastSync = os.time() + math.random(-2, 2)
    end)
end

-- ══════════════════════════════════════════════════════════════════
-- 🆕 المبدأ 19: حماية الحالة الحرجة (Critical State Shield)
-- يمنع ACE من الوصول لحالات حرجة
-- ══════════════════════════════════════════════════════════════════
local function critical_state_shield()
    pcall(function()
        local critical = {
            "bIsUnderInvestigation", "bPendingBan", "bInReview",
            "bAwaitingVerdict", "bUnderWatch", "bSuspectedPlayer",
            "bHighRiskPlayer", "bLowTrustPlayer", "bInBlacklist",
            "bInWatchlist",
        }
        
        for _, k in ipairs(critical) do
            if _G[k] ~= nil then
                _G[k] = false
            end
        end
    end)
end

-- ══════════════════════════════════════════════════════════════════
-- 🆕 المبدأ 20: درع الإغلاق الآمن (Safe Shutdown Shield)
-- في حالة الخطر الشديد، يُوقف الحماية بصمت
-- ══════════════════════════════════════════════════════════════════
local function safe_shutdown()
    pcall(function()
        local A = V.adapt
        -- لو التهديد 9+ → نُخفف النشاط
        if A.threatLevel >= 9 then
            -- إيقاف كل الحلقات النشطة
            V.adaptThrottle = true
            -- تقليل النبضات
            A.adaptCount = A.adaptCount + 1
        end
    end)
end

-- ══════════════════════════════════════════════════════════════════
-- 🆕 المبدأ 21: درع التوقيت العشوائي (Random Timing Shield)
-- نُعدّل تأخير كل الحلقات بـ jitter جديد
-- ══════════════════════════════════════════════════════════════════
local function random_timing()
    pcall(function()
        -- إنشاء رقم عشوائي يُستخدم في إعادة ترتيب الحلقات
        _G._v14_timing_seed = math.random(1, 1000)
        _G._v14_timing_offset = math.random() * 5
    end)
end

-- ══════════════════════════════════════════════════════════════════
-- 🆕 المبدأ 22: درع الحفظ الآمن (Safe Cache Shield)
-- يمنع ACE من حفظ أي شيء عنا
-- ══════════════════════════════════════════════════════════════════
local function safe_cache()
    pcall(function()
        -- منع حفظ أي بيانات عنا
        if _G.saveToCache then _G.saveToCache = function() return false end end
        if _G.persistData then _G.persistData = function() return false end end
        if _G.writeCache then _G.writeCache = function() return false end end
        if _G.storeToDisk then _G.storeToDisk = function() return false end end
        if _G.flushCache then _G.flushCache = function() return true end end
        
        -- حذف أي بيانات مخزنة سابقاً
        if _G._ACE_Cache then _G._ACE_Cache = {} end
        if _G._TSS_Cache then _G._TSS_Cache = {} end
        if _G._AC_Cache then _G._AC_Cache = {} end
    end)
end

-- ══════════════════════════════════════════════════════════════════
-- 🚀 تفعيل كل الطبقات الـ 22 (مرة واحدة)
-- ══════════════════════════════════════════════════════════════════
local function activate()
    -- المبادئ من v13
    go_silent()
    redirect_packets()
    clean_values()
    mask_identity()
    neutralize_higgs()
    hide_hooks()
    anti_scan()
    screenshot_shield()
    
    -- المبادئ الجديدة من v14
    adaptive_engine()
    fake_telemetry()
    hide_libraries()
    memory_entropy()
    thread_shield()
    anti_reverse()
    entropy_defense()
    critical_state_shield()
    safe_shutdown()
    random_timing()
    safe_cache()
    
    V._identity = true
    V.on = true
end

-- ══════════════════════════════════════════════════════════════════
-- 🔄 الحلقات الرئيسية (11 حلقة بأوقات عشوائية)
-- ══════════════════════════════════════════════════════════════════
local function start_cycles()
    local ticker = require("common.time_ticker")
    if not ticker or not ticker.AddTimerLoop then return end
    
    -- حلقة 1: تنظيف القيم (من v13)
    if not V._l1 then
        V._l1 = true
        ticker.AddTimerLoop(0, function() pcall(clean_values) end, -1, jitter(2.5, 0.8))
    end
    
    -- حلقة 2: نبضات Higgs (من v13)
    if not V._l2 then
        V._l2 = true
        ticker.AddTimerLoop(0, function() pcall(neutralize_higgs) end, -1, jitter(0.7, 0.2))
    end
    
    -- حلقة 3: التنفس (من v13)
    if not V._l3 then
        V._l3 = true
        ticker.AddTimerLoop(0, function()
            pcall(breathe)
            pcall(natural_breathing)
        end, -1, jitter(8, 2))
    end
    
    -- حلقة 4: إخفاء الهوك (من v13)
    if not V._l4 then
        V._l4 = true
        ticker.AddTimerLoop(0, function()
            pcall(hide_hooks)
            pcall(anti_scan)
        end, -1, jitter(6, 1.5))
    end
    
    -- حلقة 5: الإصلاح الذاتي (من v13)
    if not V._l5 then
        V._l5 = true
        ticker.AddTimerLoop(0, function() pcall(self_heal) end, -1, jitter(45, 8))
    end
    
    -- حلقة 6: إعادة توجيه الحزم (من v13)
    if not V._l6 then
        V._l6 = true
        ticker.AddTimerLoop(0, function()
            if NetUtil and not NetUtil._v13_redirected then
                pcall(redirect_packets)
            end
        end, -1, jitter(15, 3))
    end
    
    -- حلقة 7: تزييف الهوية (من v13)
    if not V._l7 then
        V._l7 = true
        ticker.AddTimerLoop(0, function() pcall(mask_identity) end, -1, jitter(120, 15))
    end
    
    -- 🆕 حلقة 8: المحرك التكيفي (كل 20s ± 4s)
    if not V._l8 then
        V._l8 = true
        ticker.AddTimerLoop(0, function()
            pcall(adaptive_engine)
            pcall(safe_shutdown)
        end, -1, jitter(20, 4))
    end
    
    -- 🆕 حلقة 9: التقارير الوهمية (كل 30s ± 5s)
    if not V._l9 then
        V._l9 = true
        ticker.AddTimerLoop(0, function() pcall(fake_telemetry) end, -1, jitter(30, 5))
    end
    
    -- 🆕 حلقة 10: إخفاء المكتبات + تشويش الذاكرة (كل 12s ± 2s)
    if not V._l10 then
        V._l10 = true
        ticker.AddTimerLoop(0, function()
            pcall(hide_libraries)
            pcall(memory_entropy)
            pcall(thread_shield)
        end, -1, jitter(12, 2))
    end
    
    -- 🆕 حلقة 11: الطبقات المتقدمة (كل 25s ± 5s)
    if not V._l11 then
        V._l11 = true
        ticker.AddTimerLoop(0, function()
            pcall(anti_reverse)
            pcall(entropy_defense)
            pcall(critical_state_shield)
            pcall(random_timing)
            pcall(safe_cache)
        end, -1, jitter(25, 5))
    end
end

-- ══════════════════════════════════════════════════════════════════
-- 🚀 بدء تلقائي (بدون أي رسالة في السجل)
-- ══════════════════════════════════════════════════════════════════
pcall(function()
    local ticker = require("common.time_ticker")
    if ticker and ticker.AddTimerOnce then
        ticker.AddTimerOnce(0.8, function()
            activate()
            start_cycles()
        end)
    end
end)

