        return {
            -- v13 stats
            hb = V.n1,           -- النبضات
            rd = V.n2,           -- الحزم المُعاد توجيهها
            hl = V.n3,           -- الإصلاحات الذاتية
            -- v14 stats
            ft = V.n4,           -- التقارير الوهمية
            ae = V.n5,           -- التكيفات السلوكية
            lh = V.n6,           -- إخفاء المكتبات
            me = V.n7,           -- تشويش الذاكرة
            -- معلومات إضافية
            threat = V.adapt.threatLevel,
            uptime = os.time() - V.t0,
        }
    end,
    heal = self_heal,
    breathe = breathe,
    adapt = adaptive_engine,
    telemetry = fake_telemetry,
}
