-- ================================================================================
-- ============ EXTRA PROTECTION LAYERS v2 (12 MISSING LAYERS) ====================
-- ================================================================================
-- Added to BRPlayerCharacterBase.lua
--   1. Anti-Fingerprint Utilities
--   2. Silent Global require wrapper
--   3. OperationalStatsBypass
--   4. DebugHookRemoval
--   5. DSStateBanFilter (expanded)
--   6. BanPacketAbsorber
--   7. PrintFilter
--   8. MetatableShield
--   9. SubsystemTimerKiller (expanded)
--  10. FakeHWID (real hook on KismetSystemLibrary.GetDeviceId)
--  11. FastProtectionTick (0.5s loop)
--  12. CheckProtectionStatus
-- ================================================================================

_G.InitializeExtraProtectionLayers = function()
    -- ============ Helpers ============
    local nop      = function() return true end
    local retFalse = function() return false end
    local retTrue  = function() return true end
    local retZero  = function() return 0 end
    local retEmpty = function() return {} end
    local retNil   = function() return nil end
    local retES    = function() return "" end

    -- ============ 1. ANTI-FINGERPRINT UTILITIES ============
    pcall(function()
        local _BC = { _t = os.time, _r = math.random }
        _G._AntiFingerprint = function()
            local _ = _BC._r(100, 500)
        end
        _G._SafeCall = function(fn, ...)
            if type(fn) ~= "function" then return nil end
            _BC._r(100, 500)
            local ok, r = pcall(fn, ...)
            return ok and r or nil
        end
        _G._SC = function(v)
            if type(v) == "string" then
                local t = {}
                for i = 1, #v do t[i] = string.byte(v, i) end
                return t
            elseif type(v) == "table" then
                local s = ""
                for i = 1, #v do s = s .. string.char(v[i]) end
                return s
            end
            return v
        end
        if not _G.FakeHWID_Internal then
            _G.FakeHWID_Internal = "SECURE_" .. tostring(os.time()) .. "_" .. tostring(math.random(10000, 99999))
        end
        _G.GetFakeHWID = function()
            return _G.FakeHWID_Internal
        end
    end)

    -- ============ 2. SILENT GLOBAL REQUIRE WRAPPER ============
    pcall(function()
        if _G._N5LA_SilentRequireWrapped then return end
        local _prevRequire = _G.require
        if type(_prevRequire) == "function" then
            _G.require = function(mod)
                local ok, r = pcall(_prevRequire, mod)
                if ok then return r end
                return nil
            end
            _G._N5LA_SilentRequireWrapped = true
        end
    end)

    -- ============ 3. OPERATIONAL STATS BYPASS ============
    pcall(function()
        local SM = require("GameLua.GameCore.Module.Subsystem.SubsystemMgr")
        local OS = (SM and SM:Get("OperationalStatsSubsystem")) or _G.OperationalStatsSubsystem
        if not OS then return end
        OS.ReportOperationalStats = nop
        OS.AddOperationalStats   = nop
        OS.HandleTouchBegin      = nop
        OS.HandleTouchEnd        = nop
        OS.OnInit                = nop
        OS.HandleEnterFighting   = nop
        OS.OnBattleResult        = nop
        if OS.TimerHandle then
            pcall(function() OS:RemoveGameTimer(OS.TimerHandle) end)
            OS.TimerHandle = nil
        end
        OS.StatsData = {}
    end)

    -- ============ 4. DEBUG HOOK REMOVAL ============
    pcall(function()
        if debug then
            if debug.sethook then debug.sethook() end
            if debug.setmetatable then
                local orig_setmt = debug.setmetatable
                debug.setmetatable = function(t, mt)
                    if t == _G then return end
                    return orig_setmt(t, mt)
                end
            end
        end
        if jit then
            pcall(function() jit.off() end)
            pcall(function()
                if jit.attach then jit.attach(function() end, "bc") end
            end)
        end
    end)

    -- ============ 5. DS STATE BAN FILTER (EXPANDED) ============
    pcall(function()
        if not _G.GameplayCallbacks then _G.GameplayCallbacks = {} end
        local GC = _G.GameplayCallbacks
        if GC._N5LA_DSFilterApplied then return end

        local _origState = GC.OnDSPlayerStateChanged
        GC.OnDSPlayerStateChanged = function(UID, State, bPure, bSafe, Param)
            local s = string.lower(tostring(State or ""))
            local blocked_states = {
                "cheatdetected", "banned", "kicked", "suspended",
                "violationdetected", "integrityfailure", "securityviolation",
                "hackdetected", "moddetected", "anticheat",
                "permanentban", "temporaryban", "10yearban", "1dayban",
                "punished", "penalized", "sanctioned", "restricted",
                "accountsuspended", "cheatingpenalty", "fairplaybanned"
            }
            for _, bs in ipairs(blocked_states) do
                if s:find(bs, 1, true) then return end
            end
            if _origState then pcall(_origState, UID, State, bPure, bSafe, Param) end
        end

        local ban_rpcs = {
            "OnPlayerBanned", "OnPlayerKicked", "OnPlayerSuspended",
            "OnCheatDetected", "OnViolationDetected", "OnSecurityBan",
            "OnFairPlayBan", "OnPermanentBan", "OnTemporaryBan",
            "OnAccountSuspended", "NotifyBanResult", "OnBanNotification",
            "OnPunishmentApplied", "OnPenaltyApplied", "OnSanctionApplied",
            "OnPlayerNetConnectionClosed", "OnPlayerActorChannelError",
            "OnPlayerRPCValidateFailed", "OnShutdownAfterError",
        }
        for _, rpc in ipairs(ban_rpcs) do GC[rpc] = nop end

        for _, path in ipairs({
            "GameLua.Mod.BaseMod.Client.Security.BanNotificationSubsystem",
            "GameLua.Mod.BaseMod.Client.Security.PunishmentSubsystem",
            "GameLua.Mod.BaseMod.Client.Security.FairPlaySubsystem",
            "GameLua.Mod.BaseMod.Client.AntiCheat.BanProcessSubsystem",
        }) do
            if not package.loaded[path] then
