-- ============================================================================
-- 🎯 Snap Lines System (extracted from ابو هاشم.lua - Clean & Safe)
-- ============================================================================
do
    local SL = {
        Canvas = nil,
        Lines = {},
        CanvasScaleX = 1.0,
        CanvasScaleY = 1.0,
        CanvasOffsetX = 0.0,
        CanvasOffsetY = 0.0,
        Thickness = 2.5,
        Opacity = 0.85,
        ColorVisible = {R=0, G=1, B=0},
        ColorHidden = {R=1, G=0, B=0},
        OriginOffsetY = 25,
        UpdateInterval = 0.033,
        _running = false,
    }

    local FVector2D_c, FLinearColor_c, FVector_c, SlateBP_c, WidgetBP_c
    local function _ensureImports()
        if not FVector2D_c then
            pcall(function() FVector2D_c = import("Vector2D") end)
            pcall(function() FLinearColor_c = import("LinearColor") end)
            pcall(function() FVector_c = import("Vector") end)
            pcall(function() SlateBP_c = import("SlateBlueprintLibrary") or import("/Script/UMG.SlateBlueprintLibrary") end)
            pcall(function() WidgetBP_c = import("WidgetLayoutLibrary") or import("/Script/UMG.WidgetLayoutLibrary") end)
        end
    end

    local function _isValid(obj)
        if not obj then return false end
        if slua and slua.isValid then
            local ok, v = pcall(slua.isValid, obj)
            return ok and v
        end
        return true
    end

    local function _getCanvas()
        if SL.Canvas and _isValid(SL.Canvas) then return SL.Canvas end
        local canvas = nil
        pcall(function()
            local UIT = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
            if UIT and UIT.GetMainControlBaseUI then
                local m = UIT.GetMainControlBaseUI()
                if m and slua.isValid(m) then
                    if m.CanvasPanel_0 and slua.isValid(m.CanvasPanel_0) then
                        canvas = m.CanvasPanel_0
                    elseif m.CanvasPanel_42 and slua.isValid(m.CanvasPanel_42) then
                        canvas = m.CanvasPanel_42
                    end
                end
            end
        end)
        if canvas then SL.Canvas = canvas end
        return canvas
    end

    local function _getPC()
        local pc = nil
        pcall(function()
            local GDP = require("GameLua.GameCore.Data.GameplayData")
            if GDP and GDP.GetPlayerController then pc = GDP.GetPlayerController() end
        end)
        if _isValid(pc) then return pc end
        return nil
    end

    local function _getLocalChar()
        local c = nil
        pcall(function()
            local GDP = require("GameLua.GameCore.Data.GameplayData")
            if GDP and GDP.GetPlayerCharacter then c = GDP.GetPlayerCharacter() end
        end)
        if _isValid(c) then return c end
        return nil
    end

    local function _getAllChars()
        local list = {}
        pcall(function()
            local GDP = require("GameLua.GameCore.Data.GameplayData")
            if GDP then
                if GDP.GetAllPlayerCharacters then
                    local r = GDP.GetAllPlayerCharacters()
                    if r then
                        for _, c in pairs(r) do
                            if _isValid(c) then table.insert(list, c) end
                        end
                    end
                elseif GDP.GameCharacters then
                    for _, c in pairs(GDP.GameCharacters) do
                        if _isValid(c) then table.insert(list, c) end
                    end
                end
            end
        end)
        return list
    end

    local function _atan2(y, x)
        if math.atan2 then return math.atan2(y, x) end
        if x > 0 then return math.atan(y/x)
        elseif x < 0 and y >= 0 then return math.atan(y/x) + math.pi
        elseif x < 0 and y < 0 then return math.atan(y/x) - math.pi
        elseif x == 0 and y > 0 then return math.pi/2
        elseif x == 0 and y < 0 then return -math.pi/2
        else return 0 end
    end

    local function _updateTransform(pc)
        if not _isValid(SL.Canvas) then return end
        _ensureImports()
        local ok = false
        pcall(function()
            if SlateBP_c and SlateBP_c.AbsoluteToLocal then
                local geom = SL.Canvas:GetCachedGeometry()
                if geom then
                    local p0 = SlateBP_c.AbsoluteToLocal(geom, FVector2D_c(0,0))
                    local p1 = SlateBP_c.AbsoluteToLocal(geom, FVector2D_c(100,100))
                    if p0 and p1 then
                        SL.CanvasScaleX = (p1.X - p0.X) / 100
                        SL.CanvasScaleY = (p1.Y - p0.Y) / 100
                        SL.CanvasOffsetX = p0.X
                        SL.CanvasOffsetY = p0.Y
                        ok = true
                    end
                end
            end
        end)
        if not ok then
            local s = 1.0
            pcall(function()
                if WidgetBP_c and WidgetBP_c.GetViewportScale then
                    s = WidgetBP_c.GetViewportScale(pc) or 1.0
                end
            end)
            SL.CanvasScaleX = 1.0 / s
            SL.CanvasScaleY = 1.0 / s
            SL.CanvasOffsetX = 0
            SL.CanvasOffsetY = 0
        end
    end

    local function _screenToCanvas(sp)
        _ensureImports()
        return FVector2D_c(
            sp.X * SL.CanvasScaleX + SL.CanvasOffsetX,
            sp.Y * SL.CanvasScaleY + SL.CanvasOffsetY
        )
    end

    local function _project(pc, world)
        _ensureImports()
        if not _isValid(pc) or not world then return false, FVector2D_c(0,0) end
        local sp = FVector2D_c(0,0)
        local ok = false
        pcall(function()
            local r = pc:ProjectWorldLocationToScreen(world, sp, true)
            if r == true or r == 1 or (sp and (sp.X ~= 0 or sp.Y ~= 0)) then ok = true end
        end)
        if not ok or (sp.X == 0 and sp.Y == 0) then return false, FVector2D_c(0,0) end
        return true, _screenToCanvas(sp)
    end

    local function _getOrigin(pc)
        _ensureImports()
        local w, h = 1920, 1080
        local scale = 1.0
        pcall(function()
            if WidgetBP_c and WidgetBP_c.GetViewportSize then
                local vs = WidgetBP_c.GetViewportSize(pc)
                if vs and vs.X and vs.X > 200 then w = vs.X; h = vs.Y end
            end
        end)
        pcall(function()
            if WidgetBP_c and WidgetBP_c.GetViewportScale then
                local s = WidgetBP_c.GetViewportScale(pc)
                if s and type(s) == "number" and s > 0 then scale = s end
            end
        end)
        local px = FVector2D_c(w / 2.0, SL.OriginOffsetY * scale)
        local cp = _screenToCanvas(px)
        return cp.X, cp.Y
    end

    local function _createLine()
        local canvas = SL.Canvas
        if not _isValid(canvas) then return nil end
        _ensureImports()
        local border = nil
        pcall(function() border = CGame:NewObjectFromPath("/Script/UMG.Border", canvas) end)
        if not _isValid(border) then return nil end
        pcall(function() border:SetBrushColor(FLinearColor_c(1,1,0,SL.Opacity)) end)
        pcall(function() border:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
        pcall(function() border:SetRenderTransformPivot(FVector2D_c(0.0, 0.5)) end)
        local slot = nil
        pcall(function()
            slot = canvas:AddChildToCanvas(border)
            if slot then
                slot:SetAutoSize(false)
                slot:SetZOrder(1)
            end
        end)
        return { Widget = border, Slot = slot }
    end

    local function _removeLine(key)
        local d = SL.Lines[key]
        if d and _isValid(d.Widget) then
            pcall(function()
                d.Widget:RemoveFromParent()
                d.Widget:ConditionalBeginDestroy()
            end)
        end
        SL.Lines[key] = nil
    end

    local function _updateLine(key, pos, onScreen, ox, oy, visible)
        _ensureImports()
        local d = SL.Lines[key]
        if not onScreen or not pos then
            if d and _isValid(d.Widget) then
                pcall(function() d.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
            end
            return
        end
        if not d then
            d = _createLine()
            if not d or not d.Widget or not d.Slot then return end
            SL.Lines[key] = d
        end
        pcall(function() d.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)

        local color
        if visible then
            color = FLinearColor_c(SL.ColorVisible.R, SL.ColorVisible.G, SL.ColorVisible.B, SL.Opacity)
        else
            color = FLinearColor_c(SL.ColorHidden.R, SL.ColorHidden.G, SL.ColorHidden.B, SL.Opacity)
        end
        pcall(function() d.Widget:SetBrushColor(color) end)

        local dx = pos.X - ox
        local dy = pos.Y - oy
        local length = math.sqrt(dx*dx + dy*dy)
        local thickness = SL.Thickness
        local angle = _atan2(dy, dx) * (180.0 / math.pi)

        pcall(function()
            d.Slot:SetPosition(FVector2D_c(ox, oy - thickness/2))
            d.Slot:SetSize(FVector2D_c(length, thickness))
        end)
        pcall(function() d.Widget:SetRenderAngle(angle) end)
    end

    function SL.ClearAll()
        for k, _ in pairs(SL.Lines) do _removeLine(k) end
        SL.Lines = {}
    end

    function SL.Update()
        if not _G.GTLMODConfig or not _G.GTLMODConfig.SnapLines then
            if SL._running then
                SL.ClearAll()
                SL._running = false
            end
            return
        end

        local canvas = _getCanvas()
        if not _isValid(canvas) then return end

        local pc = _getPC()
        if not _isValid(pc) then return end

        _updateTransform(pc)
        local ox, oy = _getOrigin(pc)

        local me = _getLocalChar()
        local myTeam = nil
        if _isValid(me) then
            pcall(function()
                if type(me.GetTeamID) == "function" then myTeam = me:GetTeamID() end
                if myTeam == nil then myTeam = me.TeamID end
            end)
        end

        local seen = {}
        local chars = _getAllChars()

        for _, e in ipairs(chars) do
            if e ~= me and _isValid(e) then
                local isEnemy = true
                pcall(function()
                    local tid = nil
                    if type(e.GetTeamID) == "function" then tid = e:GetTeamID() end
                    if tid == nil then tid = e.TeamID end
                    if myTeam ~= nil and tid == myTeam then isEnemy = false end
                end)

                if isEnemy then
                    local alive = true
                    pcall(function()
                        if type(e.IsAlive) == "function" then alive = e:IsAlive() end
                        if e.HealthStatus ~= nil and tonumber(e.HealthStatus) == 2 then alive = false end
                    end)

                    if alive then
                        local headPos = nil
                        pcall(function()
                            if e.Mesh and _isValid(e.Mesh) then
                                headPos = e.Mesh:GetSocketLocation("head")
                            end
                            if not headPos and type(e.K2_GetActorLocation) == "function" then
                                headPos = e:K2_GetActorLocation()
                                headPos.Z = headPos.Z + 85
                            end
                        end)

                        if headPos then
                            local key = tostring(e.PlayerKey or e)
                            seen[key] = true

                            local onScreen, cp = _project(pc, headPos)
                            local vis = false
                            pcall(function()
                                if type(pc.LineOfSightTo) == "function" then
                                    local checkVec = FVector_c and FVector_c(0,0,0) or {X=0,Y=0,Z=0}
                                    vis = pc:LineOfSightTo(e, checkVec, false)
                                end
                            end)

                            _updateLine(key, cp, onScreen, ox, oy, vis)
                        end
                    end
                end
            end
        end

        for key, _ in pairs(SL.Lines) do
            if not seen[key] then _removeLine(key) end
        end

        SL._running = true
    end

    _G.N5LA_SnapLine = SL

    -- Self-scheduling update loop
    local function _loop()
        pcall(SL.Update)
        pcall(function()
            require("common.time_ticker").AddTimerOnce(SL.UpdateInterval, _loop)
        end)
    end
    pcall(function()
        require("common.time_ticker").AddTimerOnce(1.0, _loop)
    end)
end

