-- ✅ نخلي isExpired global
_G._N5LA_isExpired = _G._N5LA_isExpired or true
local limitTime = 0
local currentTime = os.time()
-- ✅ نستخدم متغير محلي متزامن مع الـ global
local isExpired = _G._N5LA_isExpired

local function SyncLicenseState()
    local nowTime = os.time()

    -- ✅ فحص الحالة الحقيقية من N5LA_License
    local licActive = (_G.N5LA_LicenseActive == true)
    local licExpiry = 0
    if _G.N5LA_License and _G.N5LA_License.expiry then
        licExpiry = _G.N5LA_License.expiry
    end

    -- ✅ هل الكود صالح؟
    local isValid = licActive and licExpiry > 0 and nowTime <= licExpiry

    if isValid then
        isExpired = false
        _G._N5LA_isExpired = false
        limitTime = licExpiry
    else
        isExpired = true
        _G._N5LA_isExpired = true
    end

    currentTime = nowTime
end

-- ✅ استدعاء أول مرة
SyncLicenseState()

-- ✅ حلقة مزامنة أسرع (كل 0.5 ثانية) - تدعم إعادة التشغيل
if not _G._N5LA_LicenseSyncStarted then
    _G._N5LA_LicenseSyncStarted = true
    pcall(function()
        local function SyncLoop()
            pcall(SyncLicenseState)
            pcall(function()
                require("common.time_ticker").AddTimerOnce(0.5, SyncLoop)
            end)
        end
        require("common.time_ticker").AddTimerOnce(0.5, SyncLoop)
    end)
end
