local function LowEndMode()
    return _G.GTLMODConfig and _G.GTLMODConfig.LowEndDevice == true
end

local function GetEnemyVisibleCached(pc, enemy, markData)
    local now = os.clock()
    local refresh = LowEndMode() and 0.35 or 0.2
    if not markData.LV_T or (now - markData.LV_T) > refresh then
        local vis = true
        pcall(function()
            if pc and type(pc.LineOfSightTo) == "function" then vis = pc:LineOfSightTo(enemy) end
        end)
        markData.LV_T = now
        markData.LV_V = vis
    end
    return markData.LV_V
end

-- ========================================== 
-- AI (BOT) / REAL PLAYER - OPTIMIZED TEST
-- ==========================================
local function CheckIsAI(pawn, markData)
    if markData.AK_IS_BOT ~= nil then return markData.AK_IS_BOT, true end
    
    local isAI = false
    local hasChecked = false
    pcall(function()
        if pawn.bIsAI == true or pawn.IsAI == true then isAI = true; hasChecked = true end
        if type(pawn.IsBot) == "function" and pawn:IsBot() then isAI = true; hasChecked = true end
        
        local pState = pawn.PlayerState or (type(pawn.GetPlayerState) == "function" and pawn:GetPlayerState())
        if Valid(pState) then
            hasChecked = true
            if pState.bIsABot == true or pState.bIsBot == true then isAI = true end
            if type(pState.IsBot) == "function" and pState:IsBot() then isAI = true end
        end
        
        if not isAI then
            local name = pawn.PlayerName or (type(pawn.GetPlayerName) == "function" and pawn:GetPlayerName()) or ""
            if name ~= "" and (name:find("Cobra") or name:find("Target") or name:find("bot_") or name:find("b_")) then
                isAI = true
                hasChecked = true
            end
        end
    end)
    if hasChecked then markData.AK_IS_BOT = isAI end
    return isAI, hasChecked
end

