                { Key = "Cat_Aimbot_Force", Text= "تصويب تلقائي (ايم بوت)", Stack = StackAimbotForce },
                { Key = "Cat_Combat_Graphic", Text= "مميزات إضافية", Stack = StackCombatGraphic },
