        }
        
        table.insert(SettingCatalog, SettingPageDefine.ModMenu)
    end

    local UIManager = _G.UIManager
    if UIManager and not UIManager._IsModMenuHooked then
        local old_ShowUI = UIManager.ShowUI
        UIManager.ShowUI = function(config, ...)
            local args = {...}
            local n = select('#', ...) 
            
            if config and config.keyName and (string.find(string.lower(config.keyName), "setting_main") or string.find(string.lower(config.keyName), "setting")) then
                local catalog = args[1]
                if type(catalog) == "table" then
                    local hasModMenu = false
                    for _, page in ipairs(catalog) do
                        if type(page) == "table" and page.Key == "ModMenu" then
                            hasModMenu = true
                            break
                        end
                    end
                    if not hasModMenu then
                        table.insert(catalog, SettingPageDefine.ModMenu)
                    end
                end
            end
            local table_unpack = table.unpack or unpack
            return old_ShowUI(config, table_unpack(args, 1, n))
        end
        UIManager._IsModMenuHooked = true
    end
end

local function ShowGTLMODVIPMenu() 
    if _G.GTLMODMenuAlreadyShown then return end
    if _G.GTLMODState.MenuStep ~= 0 then return end

    pcall(function()
        local Msg = require("client.slua.logic.common.logic_common_msg_box")
        if not Msg or not Msg.Show then return end

        local function Step_ScamAlert()
            Msg.Show(1, "مالك المود  @MON5LA@MON5LA", " المطور @MON5LA \n استمتع ", function() local Web = require("client.slua.logic.url.logic_webview_sdk"); if Web and Web.OpenURL then Web:OpenURL(" MON5LA ") end end, function() end, "انضمام" )
            _G.GTLMODState.MenuStep = 99
            _G.GTLMODMenuAlreadyShown = true
        end

        local function Step_Welcome()
            local remain = math.max(0, math.floor((limitTime or 0) - (currentTime or 0)))
            local sRem = remain % 60
            local mRem = math.floor((remain / 60) % 60)
            local hRem = math.floor((remain / 3600) % 24)
            local dRem = math.floor(remain / 86400)
            local countdown = string.format("%d يوم : %d ساعة : %d دقيقة : %d ثانية", dRem, hRem, mRem, sRem)
            Msg.Show(1, " VIP مدفوع | @MON5LA", "تم التفعيل بنجاح!\n\nالمدة المتبقية من اشتراكك:\n" .. countdown .. "\n\nلأفضل تجربة راسلنا عبر التيليجرام.\nالمالك الحقيقي هو @MON5LA",
            function() 
                _G.InitModMenuTab()
                Notify("قائمة VIP مفعّلة بواسطة @MON5LA لفتح الميزات!\nالمتبقي: " .. countdown)
                Step_ScamAlert()
            end, 
            function() end, "موافق")
        end

        _G.GTLMODState.MenuStep = 1
        Step_Welcome() 
    end)
end

-- ========================================== 
-- LOGIC 165 FPS IPAD VIEW 
-- ========================================== 
local function InitializeGraphicsUnlock() 
    if isExpired or _G._N5LA_isExpired then return end
    if _G.GTLMODState.GraphicsUnlocked or currentTime > limitTime then return end

    pcall(function()
        local SettingCfg = require("client.logic.setting.setting_config")
        local GraphicSettingDB = require("client.slua.umg.NewSetting.GraphicsNew.GraphicSettingDB")
        if SettingCfg then
            if SettingCfg.TpViewValue then SettingCfg.TpViewValue.max = 160 end
            if SettingCfg.FpViewValue then SettingCfg.FpViewValue.max = 160 end
        end
        if GraphicSettingDB then
            if GraphicSettingDB.TpViewValue then GraphicSettingDB.TpViewValue.max = 160 end
        end
    end)

    pcall(function()
        local logic_setting_graphics = require("client.slua.logic.setting.logic_setting_graphics")
        local GSC_FPS = require("client.slua.umg.NewSetting.GraphicsNew.Comps.GSC_FPS")
        local GSC_FPSFT = require("client.slua.umg.NewSetting.GraphicsNew.Comps.GSC_FPSFT")
        local GraphicSettingDB = require("client.slua.umg.NewSetting.GraphicsNew.GraphicSettingDB")
        
        local KismetMathLibrary = import("KismetMathLibrary") or _G.KismetMathLibrary
        local FLinearColor = import("LinearColor") or _G.FLinearColor

        if logic_setting_graphics then
            local old_SetFPS = logic_setting_graphics.SetFPS
            function logic_setting_graphics.SetFPS(gameInstance, FPSLevel)
                if old_SetFPS then old_SetFPS(gameInstance, FPSLevel) end
                if FPSLevel == 8 then 
                    gameInstance:ExecuteCMD("t.MaxFPS", "165")
                    gameInstance:ExecuteCMD("r.FrameRateLimit", "165")
                end
            end
        end

        if GSC_FPS and GSC_FPS.__inner_impl then
            local fps_impl = GSC_FPS.__inner_impl
            function fps_impl:GetMaxFPSLevel() return 8, 8 end
            function fps_impl:InitRealSupportFPS()
                local RealSupportFPS = {}
                for i = 1, 8 do RealSupportFPS[i] = {true, true} end
                if GraphicSettingDB then GraphicSettingDB:UpdateUIData(GraphicSettingDB.RealSupportFPS, RealSupportFPS, false) end
                return RealSupportFPS
            end
            function fps_impl:UpdateSelectedFPSState(selectedLevel)
                if not slua.isValid(self.UIRoot) then return end
                for level = 2, 8 do
                    local name = "NodeFps" .. (({[2]=20,[3]=25,[4]=30,[5]=40,[6]=60,[7]=90,[8]=120})[level] or 120)
                    local widget = self.UIRoot[name]
                    if slua.isValid(widget) then
                        widget:SetIsEnabled(true) 
                        pcall(function() widget:SetRenderOpacity(1.0) end)
                        local switcher = self.UIRoot["WidgetSwitcher_" .. level]
                        if slua.isValid(switcher) then 
                            switcher:SetActiveWidgetIndex(level == selectedLevel and 0 or 1) 
                        end
                    end
                end
            end
        end

        if GSC_FPSFT and GSC_FPSFT.__inner_impl then
            local ft_impl = GSC_FPSFT.__inner_impl
            local NMinFPS, NStep = 90, 5
            local function clamp(value, min, max)
                if value < min then return min end
                if max < value then return max end
                return value
            end
            local function lerp(a, b, t) return a + (b - a) * t end
            local function _getColorByPercent(start, finish, percent)
                if not FLinearColor then return nil end
                return FLinearColor(lerp(start.R, finish.R, percent), lerp(start.G, finish.G, percent), lerp(start.B, finish.B, percent), lerp(start.A, finish.A, percent))
            end
            
            ft_impl.ShowOrHide = function(self)
                self:SelfHitTestInvisible()
                if self.InitFPSFTSwitch then self:InitFPSFTSwitch() end
            end

            ft_impl.InitFPSFTSwitch = function(self)
                local FPSFineTuneSwitch = GraphicSettingDB:GetUIData(GraphicSettingDB.FPSFineTuneSwitch)
                if self.UIRoot.Setting_Switch then self.UIRoot.Setting_Switch:SetSwitcherEnable2(FPSFineTuneSwitch, true) end
                if self.UIRoot.CanvasPanel_8 then self:SetWidgetVisible(self.UIRoot.CanvasPanel_8, FPSFineTuneSwitch) end
                if self.UIRoot.WidgetSwitcher_0 then self.UIRoot.WidgetSwitcher_0:SetActiveWidgetIndex(2) end
                if self.InitFPSFTValue165 then self:InitFPSFTValue165() end
            end

            ft_impl.InitFPSFTValue165 = function(self)
                local itemRoot = self.UIRoot
                local FPSFineTuneSwitch = GraphicSettingDB:GetUIData(GraphicSettingDB.FPSFineTuneSwitch)
                local FPSFineTuneNum = 165
                if FPSFineTuneSwitch then
                    FPSFineTuneNum = GraphicSettingDB:GetUIData(GraphicSettingDB.FPSFineTuneNum) or 165
                    itemRoot.Slider_screen3:SetLocked(false)
                    if FLinearColor then
                        itemRoot.ProgressBar_screen3:SetFillColorAndOpacity(FLinearColor(1.0, 1.0, 1.0, 1.0))
                        itemRoot.Slider_screen3:SetSliderHandleColor(FLinearColor(1.0, 1.0, 1.0, 1.0))
                    end
                else
                    itemRoot.Slider_screen3:SetLocked(true)
                    if FLinearColor then
                        itemRoot.ProgressBar_screen3:SetFillColorAndOpacity(FLinearColor(1.0, 0.625, 0.6, 1))
                        itemRoot.Slider_screen3:SetSliderHandleColor(FLinearColor(1.0, 0.625, 0.6, 1.0))
                    end
                end
                local FPSFineTunePer = (FPSFineTuneNum - NMinFPS) / (165 - NMinFPS)
                
                itemRoot.Veihclescreen3:SetText(tostring(FPSFineTuneNum))
                itemRoot.Slider_screen3:SetValue(FPSFineTunePer)
                itemRoot.ProgressBar_screen3:SetPercent(FPSFineTunePer)
                
                if FLinearColor then
                    local startColor = FLinearColor(1.0, 1.0, 1.0, 1.0)
                    local midColor = FLinearColor(1.0, 0.54, 0.11, 1.0)
                    local endColor = FLinearColor(1.0, 0.23, 0.15, 1.0)
                    local sliderColor = FPSFineTunePer < 0.4 and startColor or _getColorByPercent(midColor, endColor, (FPSFineTunePer - 0.4) / 0.6)
                    itemRoot.Slider_screen3:SetSliderHandleColor(sliderColor)
                end
            end

            ft_impl.OnFPSFTValueChange3 = function(self, FPSFineTuneNum)
                GraphicSettingDB:UpdateUIData(GraphicSettingDB.FPSFineTuneNum, FPSFineTuneNum)
                if self.InitFPSFTValue165 then self:InitFPSFTValue165() end
                if self:GetParentUI() then self:GetParentUI():SetDirty(true) end
                local gameInstance = GraphicSettingDB.GetGameInstance and GraphicSettingDB.GetGameInstance()
                if gameInstance then
                    gameInstance:ExecuteCMD("t.MaxFPS", tostring(FPSFineTuneNum))
                    gameInstance:ExecuteCMD("r.FrameRateLimit", tostring(FPSFineTuneNum))
                end
            end

            ft_impl.OnFPSFTSliderValueChange3 = function(self, value)
                if GraphicSettingDB:GetUIData(GraphicSettingDB.FPSFineTuneSwitch) and KismetMathLibrary then
                    local FPSFineTuneNum = KismetMathLibrary.FCeil(value * (165 - NMinFPS) / NStep) * NStep + NMinFPS
                    self:OnFPSFTValueChange3(clamp(FPSFineTuneNum, NMinFPS, 165))
                end
            end
            
            ft_impl.OnFPSFTAdd = ft_impl.OnFPSFTAdd3
            ft_impl.OnFPSFTMinus = ft_impl.OnFPSFTMinus3
            ft_impl.OnFPSFTAdd2 = ft_impl.OnFPSFTAdd3
            ft_impl.OnFPSFTMinus2 = ft_impl.OnFPSFTMinus3
            ft_impl.OnFPSFTSliderValueChange = ft_impl.OnFPSFTSliderValueChange3
            ft_impl.OnFPSFTSliderValueChange2 = ft_impl.OnFPSFTSliderValueChange3
        end
    end)
    _G.GTLMODState.GraphicsUnlocked = true
    Notify("تم فتح الرسوميات و 165 فريم | @MON5LA")
end

-- ========================================== 
-- INITIALIZE THE ESP SYSTEM (BASED)
-- ========================================== 
local function InitializeNativeESP() 
    if _G.GTLMODState.NativeESPReady then return end
    pcall(function() 
        local GamePlayTools = require("GameLua.Mod.BaseMod.Common.GamePlayTools") 
        local currentMarkCfg = GamePlayTools.GetCurrentConfig("ScreenMarkConfig") 
        local function ApplyCfg(cfg)
            if not cfg then return end 
            if cfg[1006] then 
                cfg[1006].bBindBlocked = true;
                cfg[1006].bBindOutScreen = true; 
                cfg[1006].MaxWidgetNum = 99
                cfg[1006].MaxShowDistance = 6000000; 
                cfg[1006].bScaleByDistance = false
                cfg[1006].BindSocketName = "root"; 
                cfg[1006].bUseLuaWorldSocketName = true
                cfg[1006].WorldPositionOffset = FVector(0, 0, -30) 
            end 
            cfg[8888] = { 
                UIPathName = "/Game/Mod/EvoBase/BluePrints/UIBP/QuickSign/QuickSign_TipHitEnemy_UIBP_New.QuickSign_TipHitEnemy_UIBP_New_C",
                MaxWidgetNum = 99, 
                MaxShowDistance = 6000000, 
                bBindOutScreen = true,
                bBindBlocked = true, 
                bIsBindingActor = true,
                BindSocketName = "head",
                bUseLuaWorldSocketName = true, 
                WorldPositionOffset = FVector(0, 0, 30),
                bNeedPreLoad = true,
                Priority = 2 
            } 
            cfg[9999] = { 
                UIPathName = "/Game/Mod/EvoBase/BluePrints/UIBP/QuickSign/QuickSign_TipHitEnemy_UIBP_New.QuickSign_TipHitEnemy_UIBP_New_C",
                MaxWidgetNum = 99, 
                MaxShowDistance = 6000000, 
                bBindOutScreen = true,
                bBindBlocked = true, 
                bIsBindingActor = true, 
                BindSocketName = "head",
                bUseLuaWorldSocketName = true, 
                WorldPositionOffset = FVector(0, 0, 50),
                bNeedPreLoad = true, 
                Priority = 2 
            } 
        end 
        ApplyCfg(currentMarkCfg) 
        for k, cfg in pairs(package.loaded) do 
            if type(k) == "string" and string.find(k, "ScreenMarkConfig") and type(cfg) == "table" then 
                ApplyCfg(cfg) 
            end 
        end 
    end)
    _G.GTLMODState.NativeESPReady = true 
    Notify("تم تفعيل نظام الأي‏سبي | @MON5LA") 
end

-- ========================================== 
-- LOCAL FUNCTIONS CHO LOGIC NEW ESP - OPTIMIZED
-- ========================================== 
local function GetAllSkeletalMeshes(enemy, markData)
    local curTime = os.clock()
    if markData and markData.CachedMeshes and markData.CachedMeshTime and (curTime - markData.CachedMeshTime) < 3.0 then
        local validMeshes = {}
        for _, cachedMesh in ipairs(markData.CachedMeshes) do
            if Valid(cachedMesh) then table.insert(validMeshes, cachedMesh) end
        end
        markData.CachedMeshes = validMeshes
        return validMeshes
    end

    local meshes = {}
    if Valid(enemy.Mesh) then table.insert(meshes, enemy.Mesh) end
    pcall(function()
        local SkeletalMeshClass = import("SkeletalMeshComponent")
        if SkeletalMeshClass and type(enemy.GetComponentsByClass) == "function" then
            local childs = enemy:GetComponentsByClass(SkeletalMeshClass)
            if childs then
                local count = type(childs.Num) == "function" and childs:Num() or #childs
                for i = 1, count do
                    local comp = type(childs.Get) == "function" and childs:Get(i-1) or childs[i]
                    if Valid(comp) and comp ~= enemy.Mesh then
                        table.insert(meshes, comp)
                    end
                end
            end
        end
    end)
    if markData then
        markData.CachedMeshes = meshes
        markData.CachedMeshTime = curTime
    end
    return meshes
end

-- ========================================== 
-- WALL-BOUND FUNCTION & ROOT RESTORE (menggunakan ColorConfig)
-- ==========================================
local function Undowallhackng(enemy, markData)
    pcall(function()
        if markData.WallhackApplied then
            local meshes = GetAllSkeletalMeshes(enemy, markData)
            for _, mesh in ipairs(meshes) do
                if Valid(mesh) then
                    pcall(function() if type(mesh.SetRenderCustomDepth) == "function" then mesh:SetRenderCustomDepth(false) end end)
                    for i = 0, 10 do 
                        local matInterface = mesh:GetMaterial(i)
                        if Valid(matInterface) then
                            local baseMat = matInterface:GetBaseMaterial()
                            if Valid(baseMat) then baseMat.bDisableDepthTest = false end
                        end
                    end
                end
            end
            markData.WallhackApplied = false
        end
    end)
end

local function Applywallhackng(enemy, markData)
    pcall(function()
        local meshes = GetAllSkeletalMeshes(enemy, markData)
        for _, mesh in ipairs(meshes) do
            if Valid(mesh) then 
                pcall(function()
                    if type(mesh.SetRenderCustomDepth) == "function" then
                        mesh:SetRenderCustomDepth(true)
                    end
                    if type(mesh.SetCustomDepthStencilValue) == "function" then
                        mesh:SetCustomDepthStencilValue(252) 
                    end
                end)
                for i = 0, 10 do 
                    local matInterface = mesh:GetMaterial(i)
                    if not Valid(matInterface) then break end
                    local baseMat = matInterface:GetBaseMaterial()
                    if Valid(baseMat) then
                        baseMat.bDisableDepthTest = true
                        baseMat.BlendMode = 2 
                    end
                end
            end
        end
    end)
end

-- ========================================== 
-- WALLHACK WITH COLOR FROM COLORCONFIG
-- ==========================================
local function ApplyColorBodyV2(enemy, pc, markData)
    pcall(function()
        local meshes = GetAllSkeletalMeshes(enemy, markData)
        if #meshes == 0 then return end
        
        local curTime = os.clock()
        if markData.LastVisCheckTime == nil or (curTime - markData.LastVisCheckTime) > 0.3 then
            markData.LastVisCheckTime = curTime
            local isHidden = true
            pcall(function()
                if Valid(pc) and type(pc.LineOfSightTo) == "function" then
                    if pc:LineOfSightTo(enemy) then isHidden = false else isHidden = true end
                end
            end)
            markData.CachedHiddenState = isHidden
        end
        
        local hidden = markData.CachedHiddenState
        if hidden == nil then hidden = true end
        
        -- Ambil warna dari ColorConfig
        local visibleColor = GetAppliedColor(_G.ColorConfig.VisibleColor or 4, _G.ColorConfig.Brightness)
        local invisibleColor = GetAppliedColor(_G.ColorConfig.InvisibleColor or 1, _G.ColorConfig.Brightness)
        local finalColor = hidden and invisibleColor or visibleColor
        
        local colorHash = string.format("%d_%d_%d_%d", finalColor.R, finalColor.G, finalColor.B, finalColor.A)
        local currentMeshCount = #meshes
        local isMeshChanged = (markData.LastMeshCount ~= currentMeshCount)
        
        if not isMeshChanged and markData.LastHiddenState == hidden and markData.LastColorHash == colorHash then return end
        
        if isMeshChanged and markData.MIDs then
            markData.MIDs = {}
        end

        markData.LastHiddenState = hidden
        markData.LastMeshCount = currentMeshCount
        markData.LastColorHash = colorHash
        markData.ColorApplied = true
        
        for meshIndex, mesh in ipairs(meshes) do
            if Valid(mesh) then
                pcall(function()
                    mesh.LDMaxDrawDistance = -99999
                    mesh.MaxDrawDistanceOffset = -99999
                    mesh.CachedMaxDrawDistance = -99999
                    mesh.UseScopeDistanceCulling = true
                    mesh.PrimitiveShadingStrategy = 1
                    mesh.ShadingRate = 6
                end)
                for i = 0, 10 do
                    local matInterface = mesh:GetMaterial(i)
                    if not Valid(matInterface) then break end
                    local baseMat = matInterface:GetBaseMaterial()
                    if Valid(baseMat) then
                        local matName = tostring(baseMat)
                        if string.find(matName, "Master_Mask", 1, true) then
                            if not markData.MIDs then markData.MIDs = {} end
                            
                            local meshKey = "Mesh_" .. tostring(meshIndex)
                            
                            if not markData.MIDs[meshKey] then markData.MIDs[meshKey] = {} end
                            local mid = markData.MIDs[meshKey][i]
                            if not Valid(mid) then
                                mid = mesh:CreateAndSetMaterialInstanceDynamic(i)
                                markData.MIDs[meshKey][i] = mid
                            end
                            if Valid(mid) then
                                mid:SetVectorParameterValue("颜色", finalColor)
                                mid:SetVectorParameterValue("Extra Light Color", finalColor)
                                mid:SetVectorParameterValue("Para_Color", finalColor)
                                mid:SetVectorParameterValue("Para_ColorTint", finalColor)
                                mid:SetVectorParameterValue("Para_Color_1", finalColor)
                                mid:SetVectorParameterValue("Tint", finalColor)
                                mid:SetVectorParameterValue("Color", finalColor)
                                mid:SetVectorParameterValue("BaseColor", finalColor)
                                mid:SetVectorParameterValue("BodyColor", finalColor)
                                mid:SetVectorParameterValue("MainColor", finalColor)
                                mid:SetVectorParameterValue("DiffuseColor", finalColor)
                                mid:SetVectorParameterValue("EmissiveColor", finalColor)
                                mid:SetVectorParameterValue("ParaScaleOffset", SCALE_COLOR_V2)
                            end
                        end
                    end
                end
            end
        end
    end)
end

local function UndoColorBodyV2(enemy, markData)
    pcall(function()
        if markData.ColorApplied then
            local meshes = GetAllSkeletalMeshes(enemy, markData)
            for meshIndex, mesh in ipairs(meshes) do
                if Valid(mesh) then
                    pcall(function()
                        mesh.PrimitiveShadingStrategy = 0
                        mesh.ShadingRate = 1
                    end)
                    local meshKey = "Mesh_" .. tostring(meshIndex)
                    if markData.MIDs and markData.MIDs[meshKey] then
                        for i, mid in pairs(markData.MIDs[meshKey]) do
                            if Valid(mid) then
                                local defC = {R=1, G=1, B=1, A=1}
                                mid:SetVectorParameterValue("颜色", defC)
                                mid:SetVectorParameterValue("Extra Light Color", defC)
                                mid:SetVectorParameterValue("Para_Color", defC)
                                mid:SetVectorParameterValue("Para_ColorTint", defC)
                                mid:SetVectorParameterValue("Para_Color_1", defC)
                                mid:SetVectorParameterValue("Tint", defC)
                                mid:SetVectorParameterValue("Color", defC)
                                mid:SetVectorParameterValue("BaseColor", defC)
                                mid:SetVectorParameterValue("BodyColor", defC)
                                mid:SetVectorParameterValue("MainColor", defC)
                                mid:SetVectorParameterValue("DiffuseColor", defC)
                                mid:SetVectorParameterValue("EmissiveColor", defC)
                            end
                        end
                    end
                end
            end
            markData.ColorApplied = false
            markData.LastColorHash = ""
            markData.LastHiddenState = nil
        end
    end)
end

-- ========================================== 
-- AIMBOT V2 SYSTEM WITH NEW INTEGRATED TECHNOLOGY (KISSMET SMOOTH UPDATE)
-- ========================================== 

local _targetBuffer = {}
_G.GetEnemyTargetsFromActors = function(radius)
    local result = _targetBuffer
    for i = #result, 1, -1 do result[i] = nil end
    local player = GameplayData.GetPlayerCharacter()

    if not slua.isValid(player) then
        return result
    end

    local allCharacters = {}
    if GameplayData.GetAllPlayerCharacters then
        allCharacters = GameplayData.GetAllPlayerCharacters()
    elseif GameplayData.GameCharacters then
        for _, char in pairs(GameplayData.GameCharacters) do table.insert(allCharacters, char) end
    end

    local myTeam = player:GetTeamID()

    for _, actor in pairs(allCharacters) do
        if slua.isValid(actor) and actor ~= player and actor.GetTeamID and actor:IsAlive() then
            if actor:GetTeamID() ~= myTeam then
                local dist = player:GetDistanceTo(actor)
                if dist <= radius then
                    table.insert(result, actor)
                end
            end
        end
    end
    return result
end

-- ========================================== 
-- SCAN CACHE: قائمة الأعداء تتحدث مرة واحدة كل دورة رئيسية فقط
-- (الفريم الساخن للأيم بوت يقرأ من هنا بدون استدعاءات native متكررة)
-- ========================================== 
local _N5LAAimScan = {}
local function RefreshAimScan(maxDist)
    for i = #_N5LAAimScan, 1, -1 do _N5LAAimScan[i] = nil end
    local player = GameplayData.GetPlayerCharacter()
    if not slua.isValid(player) then return end
    
    local allCharacters = {}
    if GameplayData.GetAllPlayerCharacters then
        allCharacters = GameplayData.GetAllPlayerCharacters()
    elseif GameplayData.GameCharacters then
        for _, char in pairs(GameplayData.GameCharacters) do table.insert(allCharacters, char) end
    end
    
    -- ✅ إصلاح: 3 محاولات للحصول على teamID
    local myTeam = nil
    pcall(function() myTeam = player:GetTeamID() end)
    if not myTeam then pcall(function() myTeam = player.TeamID end) end
    if not myTeam then pcall(function() myTeam = player.PlayerState and player.PlayerState.TeamNum end) end
    -- ✅ إذا فشلت كل المحاولات: نستخدم 0 كافتراضي بدلاً من إرجاع
    myTeam = myTeam or 0
    
    local count = 0
    for _, actor in pairs(allCharacters) do
        if slua.isValid(actor) and actor ~= player then
            local ok, alive, team, d = pcall(function() 
                local a = actor:IsAlive()
                local t = nil
                pcall(function() t = actor:GetTeamID() end)
                if not t then pcall(function() t = actor.TeamID end) end
                if not t then pcall(function() t = actor.PlayerState and actor.PlayerState.TeamNum end) end
                return a, t or 0, player:GetDistanceTo(actor) 
            end)
            if ok and alive and team and team ~= myTeam and d and d <= maxDist then
                _N5LAAimScan[#_N5LAAimScan + 1] = { a = actor, d = d }
                count = count + 1
            end
        end
    end
    _G._LastScanCount = count
end

-- 🧲 نظام اللصق: ذاكرة الهدف الحالي
_G._StickyTarget = _G._StickyTarget or nil
_G._StickyBone = _G._StickyBone or nil
_G._StickyTargetTime = _G._StickyTargetTime or 0
_G._StickyLockDuration = 0.35  -- مدة الثبات على الهدف (بالثواني)

-- 🧲 نظام القفل المطلق — لا يترك الهدف حتى النوك
_G._AimbotLockTarget = _G._AimbotLockTarget or nil
_G._AimbotLockBone   = _G._AimbotLockBone   or nil

-- ════════════════════════════════════════════════════════════════════
-- 🧲 نظام القفل المطلق — نسخة مُصلحة تعمل فعلياً (تعديل 2)
-- ════════════════════════════════════════════════════════════════════
_G._AimbotLockTarget  = _G._AimbotLockTarget  or nil
_G._AimbotLockBone    = _G._AimbotLockBone    or nil
_G._LastScanRefresh   = _G._LastScanRefresh   or 0

local function AimTouchHandler()
    -- ═══════════════════════════════════════════════════════════════
    -- [1] فحص التفعيل واللاعب
    -- ═══════════════════════════════════════════════════════════════
    if not _G.GTLMODConfig.AimTouchEnable then return end
    
    local player = GameplayData.GetPlayerCharacter()
    if not slua.isValid(player) then return end
    local pc = player:GetPlayerControllerSafety()
    if not slua.isValid(pc) then return end
    
    local isFiring = player.bIsWeaponFiring
    local isADS = player.bIsGunADS
    
    -- ═══════════════════════════════════════════════════════════════
    -- [2] 🔧 الإصلاح الحاسم: تحديث قائمة الأعداء إذا كانت فارغة أو قديمة
    -- (كانت هذه المشكلة الكبرى — القائمة تبقى فارغة فيبدو الأيم بوت وهمياً)
    -- ═══════════════════════════════════════════════════════════════
    local nowT = os.clock()
    if #_N5LAAimScan == 0 or (nowT - _G._LastScanRefresh) > 0.15 then
        pcall(RefreshAimScan, 40000)
        _G._LastScanRefresh = nowT
    end
    
    local enemies = _N5LAAimScan
    if #enemies == 0 then 
        _G._AimbotLockTarget = nil
        _G._AimbotLockBone = nil
        return 
    end
    
    -- ═══════════════════════════════════════════════════════════════
    -- [3] فحص السلاح (شوزن بدون ذخيرة لا يصوب)
    -- ═══════════════════════════════════════════════════════════════
    local weapon = player.WeaponManagerComponent and player.WeaponManagerComponent.CurrentWeaponReplicated
    if not weapon and type(player.GetCurrentShootWeapon) == "function" then 
        weapon = player:GetCurrentShootWeapon() 
    end
    local isShotgun, currentAmmo = false, 1
    if slua.isValid(weapon) then
        local wID = type(weapon.GetWeaponID) == "function" and weapon:GetWeaponID() or 0
        isShotgun = (wID >= 1030000 and wID < 1040000)
        if type(weapon.GetCurrentAmmo) == "function" then 
            currentAmmo = weapon:GetCurrentAmmo() 
        end
    end
    if isShotgun and currentAmmo <= 0 then return end
    
    -- ═══════════════════════════════════════════════════════════════
    -- [4] تحميل المكتبات المطلوبة (بما فيها FRotator الحقيقي)
    -- ═══════════════════════════════════════════════════════════════
    local FVector2D, UGameplayStatics, KismetMathLibrary = GetImportCache()
    local FRotator = import("Rotator")
    if not FRotator then return end
    
    local camManager = UGameplayStatics.GetPlayerCameraManager(pc, 0)
    if not slua.isValid(camManager) then return end
    local camLoc = camManager:GetCameraLocation()
    if not camLoc then return end
    
    -- ═══════════════════════════════════════════════════════════════
    -- [5] التحقق من القفل الحالي — التحرير فقط عند (نوك / موت / بعد 250م)
    -- ═══════════════════════════════════════════════════════════════
    local lockT = _G._AimbotLockTarget
    local lockB = _G._AimbotLockBone
    local lockValid = false
    
    if slua.isValid(lockT) and lockB then
        local shouldRelease = false
        pcall(function()
            -- شرط 1: النوك أو الموت
            if lockT.HealthStatus ~= nil then
                local hs = tonumber(lockT.HealthStatus)
                if hs == 1 or hs == 2 then 
                    shouldRelease = true 
                end
            end
            -- شرط 2: ميت بأي طريقة أخرى
            if type(lockT.IsAlive) == "function" and not lockT:IsAlive() then 
                shouldRelease = true 
            end
            -- شرط 3: ابتعد أكثر من 250 متر
            local ok, dist = pcall(function() return player:GetDistanceTo(lockT) end)
            if ok and dist and dist > 25000 then 
                shouldRelease = true 
            end
        end)
        if shouldRelease then
            _G._AimbotLockTarget = nil
            _G._AimbotLockBone = nil
        else
            lockValid = true
        end
    end
    
    -- ═══════════════════════════════════════════════════════════════
    -- [6] البحث عن هدف جديد (يحدث فقط عند الإطلاق أو ADS)
    -- ═══════════════════════════════════════════════════════════════
    if not lockValid and (isFiring or isADS) then
        local ui_util = GetUIUtil()
        if not ui_util then return end
        local viewportSize = ui_util.GetViewportSize()
        if not viewportSize then return end
        local centerX, centerY = viewportSize.X * 0.5, viewportSize.Y * 0.5
        
        -- ⚡ FOV 85% من الشاشة (يلتقط أي عدو أمامك)
        local FOV_RADIUS = (85 / 100.0) * (viewportSize.X / 2.0)
        
        -- 🎯 العظام المستهدفة (8 عظام - الصدر والرقبة والرأس)
        local AIM_BONES = {
            { name = "spine_02",   weight = 1.00 },  -- 🥇 الصدر
            { name = "neck_01",    weight = 0.98 },  -- 🥈 الرقبة
            { name = "head",       weight = 0.95 },  -- 🥉 الرأس
            { name = "spine_03",   weight = 1.02 },  -- صدر علوي
            { name = "spine_01",   weight = 1.04 },  -- أسفل الصدر
            { name = "clavicle_l", weight = 1.12 },  -- كتف أيسر
            { name = "clavicle_r", weight = 1.12 },  -- كتف أيمن
            { name = "pelvis",     weight = 1.25 },  -- حوض
        }
        
        local bestT, bestB, bestScore = nil, nil, 99999999
        
        for i, e in ipairs(enemies) do
            local target, tid = e.a, e.d
            if slua.isValid(target) and tid <= 15000 then
                -- تجاهل الطريح والميت
                local skip = false
                pcall(function()
                    if target.HealthStatus ~= nil then
                        local hs = tonumber(target.HealthStatus)
                        if hs == 1 or hs == 2 then skip = true end
                    end
                    if type(target.IsAlive) == "function" and not target:IsAlive() then 
                        skip = true 
                    end
                end)
                if skip then goto continue end
                
                -- فحص البوت
                local tId = type(target.GetUniqueID) == "function" and target:GetUniqueID() or tostring(target)
                _G.BotStatusCache = _G.BotStatusCache or {}
                local cachedBot = _G.BotStatusCache[tId]
                if cachedBot == nil then
                    cachedBot = IsTargetBot(target)
                    _G.BotStatusCache[tId] = cachedBot
                end
                if _G.GTLMODConfig.AimTouchIgBot and cachedBot then goto continue end
                
                -- فحص الرؤية (اختياري)
                if _G.GTLMODConfig.AimTouchVisCheck then
                    local isHidden = true
                    pcall(function() 
                        if pc:LineOfSightTo(target) then isHidden = false end 
                    end)
                    if isHidden then goto continue end
                end
                
                -- فحص كل العظام
                for _, bone in ipairs(AIM_BONES) do
                    local tPos = target:GetBonePos(bone.name, {X=0, Y=0, Z=0})
                    if tPos and not (tPos.X == 0 and tPos.Y == 0) then
                        local screen = FVector2D()
                        if pc:ProjectWorldLocationToScreen(tPos, screen, false) 
                           and screen.X > 0 and screen.Y > 0 then
                            local dx, dy = screen.X - centerX, screen.Y - centerY
                            local distScreen = math.sqrt(dx*dx + dy*dy)
                            local weightedScore = distScreen * bone.weight
                            if distScreen <= FOV_RADIUS and weightedScore < bestScore then
                                bestScore = weightedScore
                                bestT = target
                                bestB = bone.name
                            end
                        end
                    end
                end
            end
            ::continue::
        end
        
        -- 🔒 حفظ القفل على الهدف الجديد
        if slua.isValid(bestT) and bestB then
            _G._AimbotLockTarget = bestT
            _G._AimbotLockBone = bestB
            lockValid = true
        end
    end
    
    if not lockValid then return end
    
    -- ═══════════════════════════════════════════════════════════════
    -- [7] 🔧 الإصلاح الحاسم: التصويب الفعلي (4 دوال معاً = يعمل!)
    -- ═══════════════════════════════════════════════════════════════
    local finalBonePos = _G._AimbotLockTarget:GetBonePos(_G._AimbotLockBone, {X=0, Y=0, Z=0})
    if not finalBonePos or (finalBonePos.X == 0 and finalBonePos.Y == 0) then 
        return 
    end

    local rot = KismetMathLibrary.FindLookAtRotation(camLoc, finalBonePos)
    if not rot then return end
    
    -- snap 100% مع اهتزاز ضئيل جداً (±0.0002 درجة)
    local jitterYaw = (math.random(-2, 2) / 10000)
    local jitterPitch = (math.random(-2, 2) / 10000)
    
    local finalPitch = rot.Pitch + jitterPitch
    local finalYaw = rot.Yaw + jitterYaw
    
    -- ✅ إنشاء FRotator حقيقي (مهم جداً!)
    local newRot = FRotator(finalPitch, finalYaw, 0)
    
    -- ✅ الاستدعاء 1: SetControlRotation (يرسل الأمر للسيرفر)
    pcall(function() 
        pc:SetControlRotation(newRot, "HumanizedAim") 
    end)
    
    -- ✅ الاستدعاء 2: K2_SetActorRotation (يحرك الشخصية نفسها)
    pcall(function() 
        if player.K2_SetActorRotation then
            player:K2_SetActorRotation(FRotator(0, finalYaw, 0), false)
        end
    end)
    
    -- ✅ الاستدعاء 3: BaseAimRotation (يحرك الكاميرا على الشاشة) ← الأهم!
    pcall(function() 
        player.BaseAimRotation = newRot 
    end)
    
    -- ✅ الاستدعاء 4: تعديل كاميرا الشخص الثالث مباشرة (احتياطي)
    pcall(function()
        local tppCam = player.ThirdPersonCameraComponent
        if slua.isValid(tppCam) and tppCam.SetWorldRotation then
            tppCam:SetWorldRotation(newRot)
        end
    end)
end

_G.AimTouch = function()
    pcall(AimTouchHandler)
end
-- ==========================================
-- EREN ESP COUNTER V11 — PERFECT CENTER
-- Rights: @MON5LA | t.me/MON5LA
-- ==========================================
local function UpdateErenEspCounter()
    if not _G.GTLMODConfig.EspCounter then
        pcall(function()
            local b = _G._ESPCounterBuilt
            if b and b.items then
                for i = 1, #b.items do
                    local it = b.items[i]
                    if it and slua.isValid(it) then
                        pcall(function() it:RemoveFromParent() end)
                    end
                end
            end
            _G._ESPCounterBuilt = nil
            _G._ESPCounterLastText = nil
            local oR = _G._ESPCounterWidgetReal
            local oB = _G._ESPCounterWidgetBot
            if oR and slua.isValid(oR) then pcall(function() oR:RemoveFromParent() end) end
            if oB and slua.isValid(oB) then pcall(function() oB:RemoveFromParent() end) end
            _G._ESPCounterWidgetReal = nil
            _G._ESPCounterWidgetBot  = nil
        end)
        return
    end

    pcall(function()
        local bots    = _G._Counter_Bots    or 0
        local players = _G._Counter_Players or 0

        local realTxt = string.format("REAL %d", players)
        local botTxt  = string.format("BOT %d", bots)
        local stamp   = realTxt .. "|" .. botTxt

        local b = _G._ESPCounterBuilt
        if b and b.realText and slua.isValid(b.realText)
             and b.botText  and slua.isValid(b.botText) then
            if stamp ~= _G._ESPCounterLastText then
                _G._ESPCounterLastText = stamp
                pcall(function() b.realText:SetText(realTxt) end)
                pcall(function() b.botText:SetText(botTxt) end)
            end
            return
        end

        if b and b.items then
            for i = 1, #b.items do
                local it = b.items[i]
                if it and slua.isValid(it) then
                    pcall(function() it:RemoveFromParent() end)
                end
            end
        end
        _G._ESPCounterBuilt = nil

        local canvas = nil
        pcall(function()
            local UIT = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
            if UIT and UIT.GetMainControlBaseUI then
                local m = UIT.GetMainControlBaseUI()
                if m and slua.isValid(m) then
                    if m.CanvasPanel_0 and slua.isValid(m.CanvasPanel_0) then
                        canvas = m.CanvasPanel_0
                    elseif m.CanvasPanel_42 and slua.isValid(m.CanvasPanel_42) then
                        canvas = m.CanvasPanel_42
                    end
                end
            end
        end)
        if not canvas then return end

        local FLinearColor = import("LinearColor")
        local FSlateColor  = import("SlateColor") or import("/Script/SlateCore.SlateColor")
        local FVector2D    = import("Vector2D")
        local FAnchors     = rawget(_G, "FAnchors") or import("Anchors")

        local items = {}

        -- ════════ Dimensions ════════
        local CARD_W, CARD_H = 112, 34
        local GAP             = 12
        local Y_POS           = 42
        local HALF            = (CARD_W + GAP) / 2

        -- ════════ Palette ════════
        local GOLD_R, GOLD_G, GOLD_B = 1.00, 0.85, 0.35
        local BG_R, BG_G, BG_B = 0.015, 0.015, 0.022

        -- REAL: glowing TRUE RED
        local R_GLOW_R, R_GLOW_G, R_GLOW_B = 1.00, 0.10, 0.10
        local R_FR,     R_FG,     R_FB     = 0.90, 0.05, 0.05
        local R_DT_R,   R_DT_G,   R_DT_B   = 1.00, 0.30, 0.30

        -- BOT: glowing emerald-cyan
        local B_GLOW_R, B_GLOW_G, B_GLOW_B = 0.20, 1.00, 0.70
        local B_FR,     B_FG,     B_FB     = 0.10, 0.85, 0.55
        local B_DT_R,   B_DT_G,   B_DT_B   = 0.45, 1.00, 0.80

        -- ════════ Helpers ════════
        local function AddB(x, y, w, h, r, g, bl, a, z)
            local bd = CGame:NewObjectFromPath("/Script/UMG.Border", canvas)
            if not bd or not slua.isValid(bd) then return nil end
            pcall(function() bd:SetBrushColor(FLinearColor(r, g, bl, a)) end)
            local s = canvas:AddChildToCanvas(bd)
            if s then
                s:SetAutoSize(false)
                pcall(function() s:SetAnchors(FAnchors(0.5, 0.0, 0.5, 0.0)) end)
                pcall(function() s:SetAlignment(FVector2D(0.0, 0.0)) end)
                pcall(function() s:SetPosition(FVector2D(x, y)) end)
                pcall(function() s:SetSize(FVector2D(w, h)) end)
                pcall(function() s:SetZOrder(z or 20000) end)
            end
            pcall(function() bd:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
            items[#items+1] = bd
            return bd
        end

        -- ✅ النص: AutoSize + Center alignment على نقطة الموقع
        local function AddT(txt, centerX, centerY, z)
            local tb = CGame:NewObjectFromPath("/Script/UMG.TextBlock", canvas)
            if not tb or not slua.isValid(tb) then return nil end
            pcall(function() tb:SetText(txt) end)
            pcall(function()
                if tb.Font then
                    local f = tb.Font
                    f.Size = 13
                    pcall(function() f.TypefaceFontName = "Bold" end)
                    pcall(function() f.bIsBold = true end)
                    tb.Font = f
                end
            end)
            pcall(function() tb:SetColorAndOpacity(FSlateColor(FLinearColor(1.0, 1.0, 1.0, 1.0))) end)
            pcall(function() tb:SetJustification(1) end)
            pcall(function() tb:SetShadowColorAndOpacity(FLinearColor(0, 0, 0, 0.9)) end)
            pcall(function() tb:SetShadowOffset(FVector2D(1, 1)) end)
            local s = canvas:AddChildToCanvas(tb)
            if s then
                s:SetAutoSize(true)   -- ✅ يتكيف مع حجم النص
                pcall(function() s:SetAnchors(FAnchors(0.5, 0.0, 0.5, 0.0)) end)
                pcall(function() s:SetAlignment(FVector2D(0.5, 0.5)) end) -- ✅ مركز الودجت على الموقع
                pcall(function() s:SetPosition(FVector2D(centerX, centerY)) end)
                pcall(function() s:SetZOrder(z or 20010) end)
            end
            pcall(function() tb:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
            items[#items+1] = tb
            return tb
        end

        -- ════════ Card Builder ════════
        local function BuildCard(centerX, gr, gg, gb, fr, fg, fb, dr, dg, db, txt)
            local left = centerX - (CARD_W / 2)

            -- 1) Outer glow
            AddB(left - 6, Y_POS - 6, CARD_W + 12, CARD_H + 12,
                 gr, gg, gb, 0.10, 19985)
            -- 2) Mid glow
            AddB(left - 3, Y_POS - 3, CARD_W + 6, CARD_H + 6,
                 gr, gg, gb, 0.28, 19988)
            -- 3) Colored frame
            AddB(left, Y_POS, CARD_W, CARD_H,
                 fr, fg, fb, 0.95, 20000)
            -- 4) Top edge accent
            AddB(left + 1, Y_POS + 1, CARD_W - 2, 1,
                 dr, dg, db, 0.85, 20001)
            -- 5) Bottom edge accent
            AddB(left + 1, Y_POS + CARD_H - 2, CARD_W - 2, 1,
                 dr, dg, db, 0.85, 20001)
            -- 6) Dark inner core
            AddB(left + 3, Y_POS + 3, CARD_W - 6, CARD_H - 6,
                 BG_R, BG_G, BG_B, 0.98, 20002)

            -- 7) TOP gold line (shiny + halo)
            AddB(left + 14, Y_POS + 5, CARD_W - 28, 3,
                 GOLD_R, GOLD_G, GOLD_B, 0.25, 20003)
            AddB(left + 20, Y_POS + 6, CARD_W - 40, 1,
                 GOLD_R, GOLD_G, GOLD_B, 1.0, 20004)

            -- 8) BOTTOM gold line (shiny + halo)
            AddB(left + 14, Y_POS + CARD_H - 8, CARD_W - 28, 3,
                 GOLD_R, GOLD_G, GOLD_B, 0.25, 20003)
            AddB(left + 20, Y_POS + CARD_H - 7, CARD_W - 40, 1,
                 GOLD_R, GOLD_G, GOLD_B, 1.0, 20004)

            -- 9) Glowing dot (left)
            AddB(left + 6, Y_POS + (CARD_H / 2) - 4, 8, 8,
                 dr, dg, db, 0.35, 20005)
            AddB(left + 7, Y_POS + (CARD_H / 2) - 3, 6, 6,
                 dr, dg, db, 1.0, 20006)

            -- ══ 10) TEXT: centered slightly left of card center ══
            -- المركز الأفقي: مركز البطاقة ناقص 6px (لليسار قليلاً)
            -- المركز الرأسي: منتصف البطاقة بالضبط
            return AddT(txt,
                centerX - 6,               -- أفقي: قليل لليسار
                Y_POS + (CARD_H / 2),      -- رأسي: منتصف البطاقة
                20010)
        end

        -- ════════ Build both cards ════════
        local realText = BuildCard(-HALF,
            R_GLOW_R, R_GLOW_G, R_GLOW_B,
            R_FR,     R_FG,     R_FB,
            R_DT_R,   R_DT_G,   R_DT_B,
            realTxt)

        local botText = BuildCard(HALF,
            B_GLOW_R, B_GLOW_G, B_GLOW_B,
            B_FR,     B_FG,     B_FB,
            B_DT_R,   B_DT_G,   B_DT_B,
            botTxt)

        _G._ESPCounterBuilt = {
            items    = items,
            realText = realText,
            botText  = botText,
        }
        _G._ESPCounterLastText = stamp
    end)
end
-- ========================================== 
-- MAIN LOOP: EXTREMELY POWERFUL OPTIMIZED
-- ========================================== 
local function MainLoop() 
    if isExpired or _G._N5LA_isExpired then return end

    if _G.GTLMODState.CustomTextData == nil then 
        -- Sirf actually-used fields (aimbot ab unified logic mein hardcoded presets use karta hai)
        _G.GTLMODState.CustomTextData = {OuterSpeed = 10, InnerSpeed = 10, HRecoil = 0.3, VRecoil = 0.3, IpadViewFOV = 120}
    end

    if not GameplayData then return end 
    local pc = GameplayData.GetPlayerController() 
    local localPlayer = nil
    if Valid(pc) then localPlayer = pc:GetPlayerCharacterSafety() end 

    if not Valid(localPlayer) then 
        if _G.GTLMODState.TrackedMarks then
            for markId, _ in pairs(_G.GTLMODState.TrackedMarks) do
                SafeRemoveMark(markId)
            end
        end
        _G.GTLMODState.TrackedMarks = {} 
        
        for key, data in pairs(_G.GTLMODState.EnemyMarks) do
            if data and data.MIDs then
                for meshStr, midTable in pairs(data.MIDs) do
                    for k, _ in pairs(midTable) do midTable[k] = nil end
                end
                data.MIDs = nil
            end
        end
        
        _G.GTLMODState.EnemyMarks = {}
        _G.AK_OrigHitboxes = {}
        _G.AK_ModdedPhysAssets = {}
        _G.GTLMODState.PrevGraphicsState = {}
        return 
    end

    local Cached_PPM = GetPPM()
    local Cached_SecurityCommonUtils = GetSecUtils()

    RefreshAimScan(40000)
    local Cached_MyHUD = pc and pc.MyHUD or nil
-- ✅ الإصلاح الذكي: إعادة تفعيل الحماية والواجهات تلقائياً عند دخول المباراة
if Valid(localPlayer) then
    if not _G._LastPlayerRef or _G._LastPlayerRef ~= localPlayer then
        _G._LastPlayerRef = localPlayer
        pcall(function()
            -- إجبار HUD على إعادة البناء
            if _G.GTLMODConfig.EnableHUD and _G.HUD_ForceBuild then _G.HUD_ForceBuild() end
            -- إجبار الكرس هير على إعادة البناء
            if _G.GTLMODConfig.EnableCrosshair and _G.Crosshair_ForceBuild then _G.Crosshair_ForceBuild() end
            -- إجبار الحماية على إعادة التشغيل
            if _G.GTLMODConfig.EnableProtection and _G.FW11_ToggleProtection then _G.FW11_ToggleProtection(true) end
        end)
    end
else
    _G._LastPlayerRef = nil
end
    if _G.GTLMODConfig.UnlockFPS then InitializeGraphicsUnlock() end
    InitializeNativeESP()
    ShowGTLMODVIPMenu()
    
    if _G.GTLMODConfig.IpadView and _G.GTLMODState.CustomTextData then
        pcall(function()
            local targetTPP = _G.GTLMODState.CustomTextData.IpadViewFOV or 120
            local uTPPCam = localPlayer.ThirdPersonCameraComponent
            if Valid(uTPPCam) and not localPlayer.bIsWeaponAiming then
                if uTPPCam.FieldOfView ~= targetTPP then uTPPCam.FieldOfView = targetTPP end
            end
        end)
    else
        pcall(function()
            local uTPPCam = localPlayer.ThirdPersonCameraComponent
            if Valid(uTPPCam) and not localPlayer.bIsWeaponAiming then
                if uTPPCam.FieldOfView ~= 80 then uTPPCam.FieldOfView = 80 end
            end
        end)
    end

-- ========================================== 
-- SKIN MOD LOOP + KILL COUNTER + DEADBOX
-- ========================================== 
if _G.GTLMODConfig.ModSkin then
        if not _G.TDSkinLoopStarted then
            if _G.InitializeSkinModSystem then _G.InitializeSkinModSystem() end
            if _G.ForceRefreshSkinMaps then _G.ForceRefreshSkinMaps() end
            _G.TDSkinLoopStarted = true
            -- Aktifkan Kill Counter & Effect
            if not _G.KillInfoCounterHacked and _G.ForceEnableKillCounterUI then _G.ForceEnableKillCounterUI() end
        end
        
        _G.GTLMODState.SkinWasApplied = true
        local curTime = os.clock()
        if not _G.LastSkinUpdateTime or (curTime - _G.LastSkinUpdateTime) > 1.5 then
            _G.LastSkinUpdateTime = curTime
            pcall(function()
                local isAlive = type(localPlayer.IsAlive) == "function" and localPlayer:IsAlive() or true
                if isAlive then
                    if _G.ReadLiveConfig then _G.ReadLiveConfig() end
                    if _G.equip_character_avatar then _G.equip_character_avatar(localPlayer) end
                    if _G.ApplyWeaponSkins then _G.ApplyWeaponSkins(localPlayer) end
                    if _G.ApplyVehicleSkins then _G.ApplyVehicleSkins(localPlayer) end
                    if _G.HandlePetLogic then _G.HandlePetLogic() end
                    -- DeadBox skin
                    if _G.DeadBox_TemperRequest and _G.NeedCheckDeadBoxTimer > 0 then _G.DeadBox_TemperRequest(pc) end
                end
            end)
        end
    else
        if _G.GTLMODState.SkinWasApplied then
            _G.OutfitMap = {}
            _G.WeaponSkinMap = {}
            _G.VehicleSkinMap = {}
            pcall(function()
                local WeaponManager = localPlayer:GetWeaponManager()
                if Valid(WeaponManager) then
                    for slot = 1, 3 do
                        local Weapon = WeaponManager:GetInventoryWeaponByPropSlot(slot)
                        if Valid(Weapon) and Valid(Weapon.synData) then
                            local WeaponID = Weapon:GetWeaponID()
                            local SkinData = Weapon.synData:Get(7)
                            if SkinData and SkinData.defineID then
                                SkinData.defineID.TypeSpecificID = WeaponID
                                Weapon.synData:Set(7, SkinData)
                                if Weapon.SetWeaponAvatarID then pcall(function() Weapon:SetWeaponAvatarID(WeaponID) end) end
                                if Weapon.DelayHandleAvatarMeshChanged then pcall(function() Weapon:DelayHandleAvatarMeshChanged() end) end
                            end
                        end
                    end
                end
                local Vehicle = localPlayer:GetCurrentVehicle()
                if Valid(Vehicle) then
                    local VehicleAvatar = Vehicle.VehicleAvatar or Vehicle.VehicleAvatarComponent_BP or Vehicle:GetAvatarComponent()
                    if Valid(VehicleAvatar) and type(VehicleAvatar.GetDefaultAvatarID) == "function" then
                        local defId = VehicleAvatar:GetDefaultAvatarID()
                        if VehicleAvatar.ChangeItemAvatar then VehicleAvatar:ChangeItemAvatar(defId, true) end
                    end
                end
                if localPlayer.AvatarComponent2 and type(localPlayer.AvatarComponent2.OnRep_BodySlotStateChanged) == "function" then
                    localPlayer.AvatarComponent2:OnRep_BodySlotStateChanged()
                end
            end)
            _G.GTLMODState.SkinWasApplied = false
        end
        _G.TDSkinLoopStarted = false
    end

    -- ========================================== 
    -- Aimbot Force dipindahkan ke loop terpisah
    -- ========================================== 

    pcall(function()
        if _G.GTLMODConfig.CustomAimbot and localPlayer.bIsWeaponFiring and localPlayer.bIsGunADS then
            local outerRecoilVal = _G.GTLMODState.CustomTextData.OuterRecoil or 0
            if outerRecoilVal > 0 then
                local curTime = os.clock()
                
                if not _G.RecoilTargetCacheTime or (curTime - _G.RecoilTargetCacheTime) > 0.2 then
                    _G.RecoilTargetCacheTime = curTime
                    _G.HasRecoilTargetCached = false
                    
                    local ui_util = GetUIUtil()
                    if ui_util then
                        local viewportSize = ui_util.GetViewportSize()
                        if viewportSize then
                            local centerX = viewportSize.X * 0.5
                            local centerY = viewportSize.Y * 0.5
                            local FOV_RADIUS = (75 / 100.0) * (viewportSize.X / 2.0)  -- زيدها إلى 85
                            
                            local enemies = _G.GetEnemyTargetsFromActors(40000) 
                            if enemies and #enemies > 0 then
                                local FVector2D = GetImportCache()
                                for _, target in ipairs(enemies) do
                                    if slua.isValid(target) and target.HealthStatus ~= 1 then 
                                        local tPos = type(target.K2_GetActorLocation) == "function" and target:K2_GetActorLocation() or nil
                                        if tPos then
                                            local screen = FVector2D()
                                            if pc:ProjectWorldLocationToScreen(tPos, screen, false) and screen.X > 0 and screen.Y > 0 then
                                                local dx = screen.X - centerX
                                                local dy = screen.Y - centerY
                                                if math.sqrt(dx*dx + dy*dy) <= FOV_RADIUS then
                                                    _G.HasRecoilTargetCached = true
                                                    break 
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end

                if _G.HasRecoilTargetCached then
                    local currentRot = pc:GetControlRotation()
                    if currentRot then
                        local pullDownForce = (outerRecoilVal / 50.0) * 1.5
                        currentRot.Pitch = currentRot.Pitch - pullDownForce
                        pc:SetControlRotation(currentRot, "CustomAimbotRecoil")
                    end
                end
            end
        else
            _G.HasRecoilTargetCached = false
        end
    end)

    pcall(function()
        if Valid(pc) then
            if pc.HiggsBoson then pc.HiggsBoson.bMHActive = false; pc.HiggsBoson.bCallPreReplication = false end
            if pc.HiggsBosonComponent then pc.HiggsBosonComponent.bMHActive = false; pc.HiggsBosonComponent.bCallPreReplication = false end
        end
    end)

    pcall(function()
        local autoComp = localPlayer.AutoAimComp
        if Valid(autoComp) then
            if not _G.GTLMODState.OrigAutoAimCompCached then
                _G.GTLMODState.OrigAutoAimCompCached = {
                    bOnlyHitHead = autoComp.bOnlyHitHead,
                    HeadBoneName = autoComp.HeadBoneName,
                    Bones = autoComp.Bones,
                    ChestBoneName = autoComp.ChestBoneName,
                    PelvisBoneName = autoComp.PelvisBoneName,
                    HeadPriority = autoComp.AimAssistConfig and autoComp.AimAssistConfig.HeadPriority,
                    ChestPriority = autoComp.AimAssistConfig and autoComp.AimAssistConfig.ChestPriority,
                    PelvisPriority = autoComp.AimAssistConfig and autoComp.AimAssistConfig.PelvisPriority
                }
            end
            
            if _G.GTLMODConfig.AutoHead then
                autoComp.bOnlyHitHead = true
                autoComp.HeadBoneName = "Head"
                pcall(function() autoComp.Bones = {"Head"} end)
                autoComp.ChestBoneName = "Head"
                autoComp.PelvisBoneName = "Head"
                if autoComp.AimAssistConfig then
                    autoComp.AimAssistConfig.HeadPriority = 100
                    autoComp.AimAssistConfig.ChestPriority = 100
                    autoComp.AimAssistConfig.PelvisPriority = 100
                end
            else
                local orig = _G.GTLMODState.OrigAutoAimCompCached
                autoComp.bOnlyHitHead = orig.bOnlyHitHead
                autoComp.HeadBoneName = orig.HeadBoneName
                pcall(function() autoComp.Bones = orig.Bones or {"Spine_01", "Pelvis", "Head"} end)
                autoComp.ChestBoneName = orig.ChestBoneName
                autoComp.PelvisBoneName = orig.PelvisBoneName
                if autoComp.AimAssistConfig then
                    autoComp.AimAssistConfig.HeadPriority = orig.HeadPriority or 1
                    autoComp.AimAssistConfig.ChestPriority = orig.ChestPriority or 1
                    autoComp.AimAssistConfig.PelvisPriority = orig.PelvisPriority or 1
                end
            end
        end
    end)

    -- ========================================== 
    -- REMOVED WALL CLIMB AND FAST CAR LOGIC 
    -- ==========================================

    local now = os.clock()
    pcall(function()
        local lsg = require("client.slua.logic.setting.logic_setting_graphics")
        local gi = lsg.GetGameInstance()
        if gi then
            if _G.GTLMODConfig.RemoveGrass and not _G.GTLMODState.PrevGraphicsState.RemoveGrass then
                gi:ExecuteCMD("grass.DensityScale", "0")
                gi:ExecuteCMD("grass.DiscardDataOnLoad", "1")
                _G.GTLMODState.PrevGraphicsState.RemoveGrass = true
            elseif not _G.GTLMODConfig.RemoveGrass and _G.GTLMODState.PrevGraphicsState.RemoveGrass then
                gi:ExecuteCMD("grass.DensityScale", "1")
                gi:ExecuteCMD("grass.DiscardDataOnLoad", "0")
                _G.GTLMODState.PrevGraphicsState.RemoveGrass = false
            end
            
            if _G.GTLMODConfig.RemoveFog and not _G.GTLMODState.PrevGraphicsState.RemoveFog then
                gi:ExecuteCMD("r.SkyAtmosphere", "1") 
                gi:ExecuteCMD("r.Fog", "0")           
                gi:ExecuteCMD("r.VolumetricFog", "0") 
                _G.GTLMODState.PrevGraphicsState.RemoveFog = true
            elseif not _G.GTLMODConfig.RemoveFog and _G.GTLMODState.PrevGraphicsState.RemoveFog then
                gi:ExecuteCMD("r.SkyAtmosphere", "1") 
                gi:ExecuteCMD("r.Fog", "1")           
                gi:ExecuteCMD("r.VolumetricFog", "1") 
                _G.GTLMODState.PrevGraphicsState.RemoveFog = false
            end
            
            if _G.GTLMODConfig.WhiteBody and not _G.GTLMODState.PrevGraphicsState.WhiteBody then
                gi:ExecuteCMD("r.CharacterDiffuseOffset", "2")
                gi:ExecuteCMD("r.CharacterDiffusePower", "5")
                gi:ExecuteCMD("r.CharacterMinShadowFactor", "100")
                _G.GTLMODState.PrevGraphicsState.WhiteBody = true
            elseif not _G.GTLMODConfig.WhiteBody and _G.GTLMODState.PrevGraphicsState.WhiteBody then
                gi:ExecuteCMD("r.CharacterDiffuseOffset", "0")
                gi:ExecuteCMD("r.CharacterDiffusePower", "1")
                gi:ExecuteCMD("r.CharacterMinShadowFactor", "1")
