            -- ═══════════════════════════════════════════════
            local function HasStrongRealEvidence(pawn, ps)
    -- الشرط 1: PlayerController كامل (ليس AIController)
    local ctrl = nil
    pcall(function()
        if type(pawn.GetController) == "function" then
            ctrl = pawn:GetController()
        end
    end)
    if not Valid(ctrl) then return false end
    
    local cn = ""
    pcall(function()
        if type(ctrl.GetClass) == "function" then
            cn = tostring(ctrl:GetClass())
        end
    end)
    -- AIController/BotController = بوت مؤكد
    if cn:find("AIController") or cn:find("BotController") then
        return false
    end
    -- لا PlayerController = ليس لاعب حقيقي
    if not cn:find("PlayerController") then
        return false
    end
    
    -- الشرط 2: UID معقول (تم تخفيض الحد من 100 مليون إلى 1 مليون)
    local uid = 0
    pcall(function()
        uid = tonumber(ps.UID or ps.Uid or ps.PlayerID or ps.PlayerId) or 0
    end)
    if uid < 1000000 then return false end
    
    -- الشرط 3: Ping (تم جعله اختياري - لا يعتبره بوتاً إذا كان 0)
    -- بعض اللاعبين الحقيقيين لديهم ping=0 في بداية المباراة
    
    -- الشرط 4: PlayerAIType == 0 (ليس بوت)
    local aiType = 0
    pcall(function()
        aiType = tonumber(ps.PlayerAIType or ps.PlayerAITypeID or 0) or 0
    end)
    if aiType > 0 then return false end
    
    -- الشرط 5: فحوصات صريحة إضافية
    if ps.bIsABot == true or ps.bIsAI == true or ps.bIsRobot == true then
        return false
    end
    
    -- جميع الشروط تحققت = لاعب حقيقي
    return true
end

            -- ═══════════════════════════════════════════════
            -- [4] تصنيف اللاعب
            -- ═══════════════════════════════════════════════
            local function IsTargetBot(pawn)
                if not Valid(pawn) then return true end
                
                -- فلاج بوت صريح على الباون
                pcall(function()
                    if pawn.bIsAI == true or pawn.bIsBot == true or pawn.bIsABot == true then
                        return true
                    end
                end)
                -- ملاحظة: لا نستخدم return داخل pcall، لذلك نعيد الفحص
                if pawn.bIsAI == true or pawn.bIsBot == true or pawn.bIsABot == true then
                    return true
                end
                
                -- PlayerState
                local ps = nil
                pcall(function() ps = pawn.PlayerState end)
                if not Valid(ps) then
                    pcall(function()
                        if type(pawn.GetPlayerState) == "function" then
                            ps = pawn:GetPlayerState()
                        end
                    end)
                end
                
                -- بدون PlayerState = بوت/دُمية
                if not Valid(ps) then return true end
                
                -- فلاج بوت صريح على PlayerState
                if ps.bIsABot == true or ps.bIsAI == true or ps.bIsRobot == true then
                    return true
                end
                
                -- PlayerAIType > 0 = بوت (أقوى فلاج)
                local aiType = 0
                pcall(function()
                    aiType = tonumber(ps.PlayerAIType) or 0
                end)
                if aiType > 0 then return true end
                
                -- هل يوجد دليل لاعب حقيقي قوي؟
                if HasStrongRealEvidence(pawn, ps) then
                    return false  -- لاعب حقيقي
                end
                
                -- لا يوجد دليل حقيقي = بوت
                return true
            end

            -- ═══════════════════════════════════════════════
            -- [5] المرور والعد
            -- ═══════════════════════════════════════════════
            for _, tPawn in pairs(allChars) do
