                    pcall(function()
                        tt = tonumber(tPawn.TeamID)
                            or tonumber(tPawn:GetTeamID()) or 0
                    end)
                    if tt ~= myTeamId then
                        local ep = nil
                        pcall(function() ep = tPawn:K2_GetActorLocation() end)
                        if ep then
                            local dx, dy, dz = ep.X - myPos.X, ep.Y - myPos.Y, ep.Z - myPos.Z
                            if (dx*dx + dy*dy + dz*dz) <= maxDistSq then
                                local alive = true
                                pcall(function()
                                    if type(tPawn.IsAlive) == "function" then
                                        alive = tPawn:IsAlive() == true
                                    elseif tPawn.HealthStatus ~= nil then
