                                                aiT = tostring(ps.PlayerAIType or 0)
                                            end
                                            local c = tPawn:GetController()
                                            if Valid(c) then
                                                ccls = tostring(c:GetClass())
                                            end
                                        end)
                                        debugInfo[#debugInfo + 1] = {
                                            name = tostring(tPawn.PlayerName or "?"),
                                            uid = uid, ping = ping,
                                            aiType = aiT, ctrl = ccls,
                                            result = isBot and "BOT" or "REAL",
                                        }
                                    end
                                end
                            end
                        end
                    end
                end
            end

