        if i > 1 then mac = mac .. ":" end
        mac = mac .. chars:sub(math.random(1, 16), math.random(1, 16))
        mac = mac .. chars:sub(math.random(1, 16), math.random(1, 16))
    end
    G.fakeID.mac = mac
    return mac
end

function GenerateFakeSerial()
    if G.fakeID.serial then return G.fakeID.serial end
    local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    local s = ""
    for i = 1, 16 do s = s .. chars:sub(math.random(1, #chars), math.random(1, #chars)) end
    G.fakeID.serial = s
    return s
end

function GenerateFakeDeviceUUID()
    if G.fakeID.uuid then return G.fakeID.uuid end
    local chars = "0123456789abcdef"
    local function seg(n)
        local s = ""
        for i = 1, n do s = s .. chars:sub(math.random(1, 16), math.random(1, 16)) end
        return s
    end
    G.fakeID.uuid = seg(8).."-"..seg(4).."-"..seg(4).."-"..seg(4).."-"..seg(12)
    return G.fakeID.uuid
end

function GenerateFakeGPS()
    if G.fakeID.gps then return G.fakeID.gps end
    G.fakeID.gps = {
