function AntiDebugLayer()
    pcall(function()
        if debug then
            debug.sethook = nop
            debug.gethook = retNil
            debug.getinfo = function(...) 
                local o = rawget(_G, "_orig_getinfo")
                if o then return o(...) end
                return {source = "[C]", what = "C", currentline = -1}
            end
            debug.getlocal = function() return nil, nil end
            debug.getupvalue = function() return nil, nil end
        end
    end)
    G.antiDetect.AntiDebug = true
end

function AntiTraceLayer()
    pcall(function()
        _G.GetStackTrace = function() return "" end
        _G.GetCallStack = function() return {} end
        _G.GetTraceback = function() return "" end
        _G.xpcall_trace = nop
    end)
    G.antiDetect.AntiTrace = true
end

function AntiMemoryScanLayer()
    pcall(function()
        for _, name in ipairs({"MemoryScanner","MemoryScan","ProcessScanner","MemoryCheck"}) do
            local m = _G[name] or package.loaded[name]
            if m then
                for k, v in pairs(m) do
                    if type(v) == "function" then pcall(function() m[k] = nop end) end
                end
            end
        end
        _G.ScanMemory = retTrue
        _G.CheckMemory = retTrue
        _G.VerifyMemory = retTrue
    end)
    G.antiDetect.AntiMemory = true
end

