-- ══════════════════════════════════════════════════════════════════
function ApplyAllSpoofing()
    GenerateFakeHWID(); GenerateFakeAndroidID(); GenerateFakeIMEI()
    GenerateFakeMAC(); GenerateFakeSerial(); GenerateFakeDeviceUUID()
    GenerateFakeGPS(); GenerateFakeBootloader(); GenerateFakeSessionID()
    GenerateFakeAdID(); GenerateFakeKernelVersion(); GenerateFakeBuildID()
    GenerateFakeBootID(); GenerateFakeCPUSerial(); GenerateFakeDiskSerial()
    GenerateFakeBoardSerial(); GenerateFakeSMSID(); GenerateFakeSIMID()

    SpoofSystemInfo(); SpoofKismet(); SpoofFApp(); SpoofCloud()
