function Shield_UnifiedMeta()
    pcall(function()
        if RS._metaApplied then return end
        RS._metaApplied = true
        local sensitive_keys = {
            ReportQueue = true, TelemetryQueue = true, ViolationList = true,
            AntiCheatFlag = true, CheatDetected = true, TrustScore = true,
            SecurityFlag = true, ViolationLevel = true, RiskScore = true,
            bIsBanned = true, bBanned = true, bIsReported = true,
            bIsCheating = true, AntiCheatScore = true, CheatScore = true,
        }
        RS._origGIndex = RS._origGIndex or (getmetatable(_G) and getmetatable(_G).__index)
        RS._origGMeta = getmetatable(_G) or {}
        RS._origGMeta.__index = function(t, k)
            if sensitive_keys[k] then return nil end
            if RS._origGIndex then return RS._origGIndex(t, k) end
            return rawget(t, k)
        end
        setmetatable(_G, RS._origGMeta)
    end)
    RS.layersActive = RS.layersActive + 1
end

