function Shield_RealPacketFilter()
    pcall(function()
        if not NetUtil or not NetUtil.SendPacket then return end
        if NetUtil._UG81_Filter then return end
        local orig = NetUtil.SendPacket
        local dangerous_packets = {
            ["on_tss_sdk_anti_data"] = true, ["tss_sdk_report"] = true,
            ["client_anti_cheat_report"] = true, ["report_speed_hack"] = true,
            ["report_wall_hack"] = true, ["report_aim_bot"] = true,
