            ["detect_cheat"] = true, ["ban_player"] = true,
            ["CheatDetection"] = true, ["ViolationReport"] = true, ["SecurityViolation"] = true,
        }
        NetUtil.SendPacket = function(packetName, ...)
            if type(packetName) == "string" and dangerous_packets[packetName] then
                RS.packetsBlocked = RS.packetsBlocked + 1
                return nil
            end
            return orig(packetName, ...)
        end
        NetUtil._UG81_Filter = true
    end)
    RS.layersActive = RS.layersActive + 1
end

