function IsMainProtectionActive()
    return _G._N5LA_PROT and _G._N5LA_PROT.active == true
end

function GetInstalledLayers()
    if not _G._N5LA_PROT or not _G._N5LA_PROT.installed then return 0 end
    local count = 0
    for _ in pairs(_G._N5LA_PROT.installed) do count = count + 1 end
    return count
end

function IsHiggsDisabled()
    local ok = false
    pcall(function()
        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
        if slua.isValid(pc) then
            if pc.HiggsBoson and pc.HiggsBoson.bMHActive == false then ok = true end
            if pc.HiggsBosonComponent and pc.HiggsBosonComponent.bMHActive == false then ok = true end
        end
    end)
    return ok
end

function IsNetworkBlocked()
    return NetUtil and NetUtil.IsBypassed == true
end

function IsPrintFiltered()
    return _G._PrintFilterActive == true
end

function IsHWIDFaked()
    return _G.FakeHWID_Hooked == true or _G.GetDeviceId ~= nil
end

function CrossCheckProtection()
    local r = {}
    r.main       = IsMainProtectionActive()
    r.layers     = GetInstalledLayers()
    r.higgs      = IsHiggsDisabled()
    r.network    = IsNetworkBlocked()
    r.print      = IsPrintFiltered()
    r.hwid       = IsHWIDFaked()
    r.spoof      = G.spoofed
    r.antiBan    = true
    r.score      = 0
    if r.main then r.score = r.score + 15 end
    if r.layers >= 20 then r.score = r.score + 15 end
    if r.higgs then r.score = r.score + 10 end
    if r.network then r.score = r.score + 10 end
    if r.hwid then r.score = r.score + 10 end
    if r.spoof >= 30 then r.score = r.score + 25 end
    if G.detectsBlocked > 0 then r.score = r.score + 10 end
    if G.hooksBlocked > 0 then r.score = r.score + 5 end
    return r
end

function MonitorProtection()
    G.checksRun = G.checksRun + 1
    G.lastCheck = os.time()
    local check = CrossCheckProtection()
    local issues = 0
    if not check.main then issues = issues + 1 end
    if check.layers < 20 then issues = issues + 1 end
    if not check.higgs then issues = issues + 1 end
    if not check.network then issues = issues + 1 end
    if not check.hwid then issues = issues + 1 end

    if issues == 0 then G.status = "PERFECT"
    elseif issues <= 2 then G.status = "GOOD"
    elseif issues <= 4 then G.status = "WARNING"; G.warnings = G.warnings + 1
    else G.status = "CRITICAL"; G.warnings = G.warnings + 1 end

    if issues > 0 then
        pcall(function()
            if _G._N5LA_PROT and not _G._N5LA_PROT.active then
                if _G.StartBypass_VIP_v3 then
                    _G.StartBypass_VIP_v3()
                    G.autoRepairs = G.autoRepairs + 1
                    Log("🔧 Auto-repair: protection restarted")
                end
            end
            if not check.hwid then
                ApplyAllSpoofing()
                G.autoRepairs = G.autoRepairs + 1
                Log("🔧 Auto-repair: spoofing reapplied")
            end
        end)
    end
end

function AntiBanCheck()
    local ok = true
    pcall(function()
        for _, v in ipairs({
            "bIsBanned","bBanned","BanStatus","bIsCheating",
            "CheatDetected","AntiCheatFlag","bIsReported",
            "SecurityFlag","ViolationLevel","TrustScore",
            "bIsSuspicious","SuspicionLevel","RiskScore",
            "bIsFlagged","bIsWatched","bIsMonitor","bIsTracked",
            "AntiCheatScore","CheatScore","RiskLevel",
            "bIsBlacklisted","bIsWhitelisted","BanReason",
            "BanExpiry","BanType","BanID","ViolationID"
        }) do
            if _G[v] ~= nil and _G[v] ~= false and _G[v] ~= 0 then
                _G[v] = nil
                ok = false
            end
        end
        if _G.GameplayCallbacks then
            for k, v in pairs(_G.GameplayCallbacks) do
                if type(k) == "string" then
                    local l = k:lower()
                    if l:find("ban") or l:find("kick") or l:find("report")
                    or l:find("cheat") or l:find("detect") then
                        _G.GameplayCallbacks[k] = nop
                    end
                end
            end
        end
    end)
    if not ok then G.antiBanClears = G.antiBanClears + 1 end
    return ok
end

function ReportToFile()
    pcall(function()
        local path = "//storage/emulated/0/Android/data/com.tencent.ig/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/.MON5LA_guardian_v3_report.txt"
        local f = io.open(path, "w")
