            f:write(string.format("Uptime: %d seconds\n", os.time() - G.started))
            f:write(string.format("Checks: %d\n", G.checksRun))
            f:write(string.format("Warnings: %d\n", G.warnings))
            f:write(string.format("Status: %s\n", G.status))
            f:close()
        end
    end)
end

