    local function readFile(p)
        local f = io.open(p, "r"); if not f then return nil end
        local c = f:read("*a"); f:close(); return c
    end

    local function buildJSON(rules)
        local parts = {}
        local function add(pkg, port, srv, srvType)
            parts[#parts+1] = string.format(
                '{"appName":"FW","isCustom":true,"mobile":"deny",'..
                '"pkg1Name":"%s","port":%d,"priority":10,"proto":"tcp",'..
                '"server":"%s","serverStrType":"%s","wifi":"deny"}',
                pkg, port, srv, srvType)
        end
        for _, pkg in ipairs(rules.packages) do
            for _, d in ipairs(rules.domains) do add(pkg, -1, d, "host") end
            for _, ip in ipairs(rules.ips or {}) do add(pkg, -1, ip, "ip4") end
            for _, port in ipairs(rules.ports) do add(pkg, port, "*", "ip4") end
            for _, cidr in ipairs(rules.ipBlocks) do add(pkg, -1, cidr, "ip4") end
        end
        return '{"apps":[],"filters":['..table.concat(parts,",")..']}'
    end

    local function ensureFile()
        for _, p in ipairs(PATHS) do
            local c = readFile(p)
            if c and #c > 50 then return c, p end
        end
        local json = buildJSON(FALLBACK)
        for _, p in ipairs(PATHS) do
            local w = io.open(p, "w")
            if w then
                local ok = pcall(function() w:write(json); w:close() end)
                if ok then return json, p end
            end
        end
        return json, "memory"
    end

    -- ═══════════════════════════════════════════════════════════
    -- SMART JSON EXTRACTOR
    -- ═══════════════════════════════════════════════════════════
    local function extract(raw)
        local out = {}
        if not raw or #raw < 20 then return out end
        local i, len = 1, #raw
        while i <= len do
            local s = raw:find("{", i, true); if not s then break end
            local depth, j, closed = 0, s, false
            while j <= len do
                local ch = raw:sub(j, j)
                if ch == "{" then depth = depth + 1
                elseif ch == "}" then
                    depth = depth - 1
                    if depth == 0 then closed = true; break end
                end
                j = j + 1
            end
            if not closed then break end
            local obj = raw:sub(s, j)
            if obj:find('"appName"',1,true) and obj:find('"pkg1Name"',1,true) and obj:find('"port"',1,true) then
                out[#out+1] = {
                    pkg1Name = obj:match('"pkg1Name"%s*:%s*"([^"]*)"') or "",
                    port     = tonumber(obj:match('"port"%s*:%s*(-?%d+)')) or -1,
                    server   = obj:match('"server"%s*:%s*"([^"]*)"') or "*",
                    stype    = obj:match('"serverStrType"%s*:%s*"([^"]*)"') or "ip4",
                    wifi     = obj:match('"wifi"%s*:%s*"([^"]*)"') or "none",
                    mobile   = obj:match('"mobile"%s*:%s*"([^"]*)"') or "none",
                }
            end
            i = j + 1
        end
        return out
    end

    local function getCurrentPkg()
        local pkg = ""
        pcall(function()
            local KSL = import("KismetSystemLibrary")
            if KSL and KSL.GetGameBundleId then pkg = KSL.GetGameBundleId() or "" end
        end)
        return pkg
    end

    -- ═══════════════════════════════════════════════════════════
    -- BLOCKING RULES
    -- ═══════════════════════════════════════════════════════════
    local Block = { domains={}, ips={}, ports={}, ipBlocks={} }
    local Stats = { total=0, deny=0, allow=0, domains=0, ips=0, ports=0, cidrs=0, hooks=0 }

    local function extractHost(srv)
        if not srv or srv == "*" or srv == "" then return nil end
        return srv:match("^([^/%s]+)")
    end

    local function rebuild(filters, currentPkg)
        Block = { domains={}, ips={}, ports={}, ipBlocks={} }
        Stats = { total=#filters, deny=0, allow=0, domains=0, ips=0, ports=0, cidrs=0, hooks=0 }

        local allowPorts, allowHosts = {}, {}
        for _, f in ipairs(filters) do
            if f.wifi == "allow" or f.mobile == "allow" then
                Stats.allow = Stats.allow + 1
                if f.pkg1Name == "*" or f.pkg1Name == currentPkg then
                    if not (f.server == "*" and f.port == -1) then
                        if f.port and f.port > 0 then allowPorts[f.port] = true end
                        local h = extractHost(f.server)
                        if h then allowHosts[h:lower()] = true end
                    end
                end
            end
        end

        for _, f in ipairs(filters) do
            if f.wifi == "deny" or f.mobile == "deny" then
                Stats.deny = Stats.deny + 1
                if f.pkg1Name == "*" or f.pkg1Name == currentPkg then
                    local srv = f.server
                    local h = extractHost(srv)
                    if h then
                        if f.stype == "host" then
                            if not allowHosts[h:lower()] then
                                Block.domains[h:lower()] = true
                                Stats.domains = Stats.domains + 1
                            end
                        elseif f.stype == "ip4" then
                            if srv:match("/") then
                                Block.ipBlocks[#Block.ipBlocks+1] = srv
                                Stats.cidrs = Stats.cidrs + 1
                            else
                                Block.ips[h] = true
                                Stats.ips = Stats.ips + 1
                            end
                        end
                    end
                    if f.port and f.port > 0 and not allowPorts[f.port] then
                        Block.ports[f.port] = true
                        Stats.ports = Stats.ports + 1
                    end
                end
            end
        end
    end

    local function ipInBlock(ip)
        for _, cidr in ipairs(Block.ipBlocks) do
            local base, pre = cidr:match("^([^/]+)/(%d+)$")
            if base and pre then
                pre = tonumber(pre)
                if pre == 8 or pre == 16 or pre == 24 then
                    local n = pre / 8
                    local p = {}
                    for part in base:gmatch("%d+") do p[#p+1] = part end
                    local pat = ""
                    for k = 1, n do
                        if p[k] then pat = pat..p[k]; if k < n then pat = pat.."." end end
                    end
                    if pat ~= "" and ip:sub(1, #pat) == pat then return true end
                end
            end
        end
        return false
    end

    local function hostBlocked(host)
        if not host or host == "" then return false end
        host = host:lower()
        if Block.domains[host] or Block.ips[host] or ipInBlock(host) then return true end
        for p in pairs(Block.domains) do
            if p:sub(1,2) == "*." then
                local suf = p:sub(2)
                if #host > #suf and host:sub(-#suf) == suf then return true end
            end
        end
        return false
    end

    local function portBlocked(port)
        return port and port > 0 and Block.ports[port] == true
    end

