end

_G.FW11_RestartShield = function()
    if _G._FW11_Loaded then pcall(installAllLayers) end
end
_G.FW11_ToggleProtection = function(isEnabled)
    if isEnabled then
        -- تفعيل الحماية
        if NetUtil and NetUtil._FW11_OrigSendPacket then
            NetUtil.SendPacket = NetUtil._FW11_OrigSendPacket
        end
        NetUtil._FW11 = false 
        pcall(installAllLayers) 
        if _G.MON5LANotiff then _G.MON5LANotiff("تم تفعيل حماية التمويه بنجاح") end
    else
        -- إيقاف الحماية (إرجاع دالة اللعبة الأصلية)
        if NetUtil and NetUtil._FW11_OrigSendPacket then
            NetUtil.SendPacket = NetUtil._FW11_OrigSendPacket
        end
        if _G.MON5LANotiff then _G.MON5LANotiff("تم إيقاف حماية التمويه يرجى إعادة تشفيها") end
    end
end
    local function installAllLayers()
            -- L1: NetUtil.SendPacket (آمن 100% - يمنع التقارير المعروفة حرفياً فقط)
pcall(function()
    if not (NetUtil and NetUtil.SendPacket) then return end
    if NetUtil._FW11 then return end
    
    if not NetUtil._FW11_OrigSendPacket then
        NetUtil._FW11_OrigSendPacket = NetUtil.SendPacket
    end
    
    local orig = NetUtil._FW11_OrigSendPacket
    NetUtil._FW11_OrigSendPacket = orig -- <--- أضف هذا السطر هنا لحفظ الدالة الأصلية
    
    NetUtil.SendPacket = function(name, ...)
        if _G.GTLMODConfig.EnableProtection == false then
            return orig(name, ...) -- إذا كان الزر مغلق، تمرر الحزم بدون حظر
        end
        -- كلمات مفتاحية للحزم الطبيعية (اللعب، الضرب، الدخول) لا يجب حظرها
        local safe_patterns = {
            "enter", "loading", "ready", "handshake", "login", "match", "join", "start", 
            "sync", "team", "ping", "heartbeat", "move", "fire", "hit", "damage", 
            "shoot", "weapon", "state", "position", "jump", "parachute", "vehicle"
        }
        
        if type(name) == "string" then
            local l = name:lower()
            local is_safe = false
            for _, sp in ipairs(safe_patterns) do
                if l:find(sp, 1, true) then is_safe = true; break end
            end
            
            -- إذا كانت الحزمة آمنة (لعب طبيعي) نمررها فوراً لكي يرى السيرفر أننا طبيعيون
            if is_safe then
                return orig(name, ...)
            end
            
            -- إذا كانت الحزمة تقرير أو غش، نحظرها
            if BLOCKED_PACKETS[name] then return nil end
            for _, pat in ipairs(BLOCK_PATTERNS) do
                if l:find(pat, 1, true) then return nil end
            end
        end
        return orig(name, ...)
    end
    NetUtil._FW11 = true; markLayer("L1_NetUtil_Smart")
end)

        -- L2: socket.connect
        pcall(function()
            if not (socket and socket.connect) or socket._FW11 then return end
            local orig = socket.connect
            socket.connect = function(host, port, ...)
                if hostBlocked(host) or portBlocked(port) then return nil, "firewall" end
                return orig(host, port, ...)
            end
            socket._FW11 = true; markLayer("L2_Socket")
        end)

        -- L3/L4: Http
        pcall(function()
            if not _G.Http then return end
            if _G.Http.Get and not _G.Http._FW11G then
                local o = _G.Http.Get
                _G.Http.Get = function(url, ...)
                    local h = type(url)=="string" and url:match("^https?://([^/:%s]+)")
                    if h and hostBlocked(h) then return nil, "blocked" end
                    return o(url, ...)
                end
                _G.Http._FW11G = true; markLayer("L3_HttpGet")
            end
            if _G.Http.Post and not _G.Http._FW11P then
                local o = _G.Http.Post
                _G.Http.Post = function(url, ...)
                    local h = type(url)=="string" and url:match("^https?://([^/:%s]+)")
                    if h and hostBlocked(h) then return nil, "blocked" end
                    return o(url, ...)
                end
                _G.Http._FW11P = true; markLayer("L4_HttpPost")
            end
        end)

        -- L5: TssSdk OnRecvData
        pcall(function()
            local T = _G.TssSdk or package.loaded["TssSdk"]
            if not T or T._FW11R then return end
            local origRecv = T.OnRecvData
            T.OnRecvData = function(data)
                if type(data) == "string" then
                    local d = data:lower()
                    if d:find("cheat",1,true) or d:find("hack",1,true) or
                       d:find("report",1,true) or d:find("violation",1,true) or
                       d:find("detect",1,true) or d:find("exception",1,true) then
                        return
                    end
                end
                if origRecv then return origRecv(data) end
            end
            T._FW11R = true; markLayer("L5_TssRecv")
        end)

        -- L6-L7: TssSdk functions
        pcall(function()
            local T = _G.TssSdk or package.loaded["TssSdk"]
            if not T or T._FW11F then return end
            T.SendReportInfo = function() end
            T.ScanMemory = function() return true end
            T.CheckIntegrity = function() return true end
            T.VerifySignature = function() return true end
            T.IsEmulator = function() return false end
            T.CheckEnvironment = function() return true end
            T.VerifyProcess = function() return true end
            T.CollectEvidence = function() return {} end
            T.GetTssSdkReportInfo = function() return "" end
            T.ReportViolation = function() end
            T.ReportCheat = function() end
            T._FW11F = true; markLayer("L6-TssSend+Scan")
        end)

        -- L8: HiggsBoson
        pcall(function()
            local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
