        -- ═══════════════════════════════════════════════════════════
    -- CLEAN UI HELPERS & NOTIFICATIONS (No Floating Button)
    -- ═══════════════════════════════════════════════════════════
    local FLinearColor = import("LinearColor")
    local FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor")
    local FVector2D = import("Vector2D")
    local FAnchors = rawget(_G, "FAnchors") or import("Anchors")

    local function toL(c)
        if not c or not FLinearColor then return c end
        local ok, r = pcall(FLinearColor, c.R or 0, c.G or 0, c.B or 0, c.A or 1)
        return ok and r or c
    end
    local function toS(c)
        local l = toL(c)
        if FSlateColor and l then
            local ok, r = pcall(FSlateColor, l); return ok and r or l
        end
        return l
    end

    local function getCanvas()
        local c = nil
        pcall(function()
            local UIT = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
            if UIT and UIT.GetMainControlBaseUI then
                local m = UIT.GetMainControlBaseUI()
                if m and slua.isValid(m) then
                    if m.CanvasPanel_42 and slua.isValid(m.CanvasPanel_42) then
                        c = m.CanvasPanel_42
                    elseif m.CanvasPanel_0 and slua.isValid(m.CanvasPanel_0) then
                        c = m.CanvasPanel_0
                    end
                end
            end
        end)
        return c
    end

    -- دالة إظهار الرسائل (تستخدم للتفعيل والإيقاف)
    local function showToast(text, isOk)
        pcall(function()
            local canvas = getCanvas(); if not canvas then return end
            local W, H = 340, 58
            local box = CGame:NewObjectFromPath("/Script/UMG.SizeBox", canvas)
            if not box or not slua.isValid(box) then return end
            pcall(function() box:SetWidthOverride(W) end)
            pcall(function() box:SetHeightOverride(H) end)

            local g = CGame:NewObjectFromPath("/Script/UMG.Border", box)
            if not g then return end
            pcall(function() g:SetBrushColor(toL(isOk and {R=0.2,G=1,B=0.5,A=1} or {R=1,G=0.3,B=0.3,A=1})) end)
            pcall(function() g:SetPadding({Left=2,Top=2,Right=2,Bottom=2}) end)
            pcall(function() box:AddChild(g) end)

            local bg = CGame:NewObjectFromPath("/Script/UMG.Border", g)
            if not bg then return end
            pcall(function() bg:SetBrushColor(toL({R=0.01,G=0.02,B=0.05,A=0.98})) end)
            pcall(function() bg:SetPadding({Left=16,Top=10,Right=16,Bottom=10}) end)
            pcall(function() g:AddChild(bg) end)

            local txt = CGame:NewObjectFromPath("/Script/UMG.TextBlock", bg)
            if txt then
                pcall(function() txt:SetText(text) end)
                pcall(function()
                    local f = txt.Font; f.Size = 18
                    pcall(function() f.TypefaceFontName = "Bold" end)
                    txt.Font = f
                end)
                pcall(function() txt:SetColorAndOpacity(toS({R=1,G=1,B=1,A=1})) end)
                pcall(function() txt:SetJustification(1) end)
                pcall(function() bg:AddChild(txt) end)
            end

            local slot = canvas:AddChildToCanvas(box)
            if slot then
                pcall(function()
                    slot:SetAutoSize(false)
                    if FAnchors then slot:SetAnchors(FAnchors(0.5,0.10,0.5,0.10)) end
                    slot:SetAlignment(FVector2D(0.5,0.5))
                    slot:SetPosition(FVector2D(0,0))
                    slot:SetSize(FVector2D(W,H))
                    slot:SetZOrder(999999)
                end)
            end

            require("common.time_ticker").AddTimerOnce(3.0, function()
                if box and slua.isValid(box) then pcall(function() box:RemoveFromParent() end) end
            end)
        end)
    end

     
