    local function getTouchPos()
        local pc = nil
        pcall(function()
            local GD = package.loaded["GameLua.GameCore.Data.GameplayData"]
            if GD and GD.GetPlayerController then pc = GD.GetPlayerController() end
        end)
        if not slua.isValid(pc) then return nil end

        if type(pc.TouchX) == "number" and type(pc.TouchY) == "number" then
            return pc.TouchX, pc.TouchY
        end

        if type(pc.GetInputTouchState) == "function" then
            local ok, a, b, c = pcall(function() return pc:GetInputTouchState(0) end)
            if ok then
                if type(a) == "number" and type(b) == "number" then return a, b end
                if type(a) == "boolean" and type(b) == "number" and type(c) == "number" then return b, c end
            end
        end

        if type(pc.GetMousePosition) == "function" then
            local ok, a, b, c = pcall(function() return pc:GetMousePosition() end)
            if ok then
                if type(a) == "number" and type(b) == "number" then return a, b end
                if type(a) == "boolean" and type(b) == "number" and type(c) == "number" then return b, c end
            end
        end

        return nil
    end

