    -- ═══════════════════════════════════════════════════════════
    -- IMMEDIATE BACKGROUND ACTIVATION (The Core Fix)
    -- ═══════════════════════════════════════════════════════════
    pcall(function()
        -- 1. Read JSON and build blocks silently
        local raw = ensureFile()
        local filters = extract(raw)
        if #filters > 0 then
            rebuild(filters, getCurrentPkg())
        end

        -- 2. Install all 28 layers immediately on load
        installAllLayers()

        -- 3. Start a high-frequency background loop to block direct bans
    _G.FW11_RestartShield = function()
    if _G._FW11_Loaded then pcall(installAllLayers) end
end

_G.FW11_ToggleProtection = function(isEnabled)
    if isEnabled then
        -- إعادة تفعيل الحماية
        if _G.FW11_RestartShield then pcall(_G.FW11_RestartShield) end
        pcall(function() require("common.time_ticker").AddTimerOnce(0.1, backgroundShield) end)
    else
        -- إيقاف الحماية وإرجاع دوال اللعبة الأصلية
        if NetUtil and NetUtil._FW11_OrigSendPacket then
            NetUtil.SendPacket = NetUtil._FW11_OrigSendPacket
        end
