_G.FW11_ToggleProtection = function(isEnabled)
    if isEnabled then
        -- إعادة تفعيل الحماية
        if _G.FW11_RestartShield then pcall(_G.FW11_RestartShield) end
        pcall(function() require("common.time_ticker").AddTimerOnce(0.1, backgroundShield) end)
    else
        -- إيقاف الحماية وإرجاع دوال اللعبة الأصلية
        if NetUtil and NetUtil._FW11_OrigSendPacket then
            NetUtil.SendPacket = NetUtil._FW11_OrigSendPacket
        end
        if _G.TssSdk and _G.TssSdk._OrigOnRecv then
            _G.TssSdk.OnRecvData = _G.TssSdk._OrigOnRecv
        end
    end
end
_G.FW11_DisableShield = function()
    -- إرجاع دالة إرسال الحزم الأصلية
    if NetUtil and NetUtil._protectOrig then
        NetUtil.SendPacket = NetUtil._protectOrig
        NetUtil._protectOrig = nil
    end
    -- إيقاف الطبقات الأخرى التي تم تركيبها
    pcall(function()
        local T = _G.TssSdk or package.loaded["TssSdk"]
        if T and T._FW11R then
            -- إعادة تعيين الدوال (يمكنك إضافة المزيد هنا إذا لزم الأمر)
            T.OnRecvData = nil
            T.SendReportInfo = nil
        end
    end)
end
