        -- ✅ الدالة النهائية لربط زر الإعدادات بالحماية
        -- ═══════════════════════════════════════════════════════════
        _G.FW11_ToggleProtection = function(isEnabled)
            if isEnabled then
                -- تفعيل الحماية
                if _G._FW11_Loaded then pcall(installAllLayers) end
                pcall(function() require("common.time_ticker").AddTimerOnce(0.1, backgroundShield) end)
                if showToast then pcall(showToast, "✅ تم تفعيل حماية التمويه", true) end
            else
                -- إيقاف الحماية وإرجاع دوال اللعبة الأصلية
                if NetUtil and NetUtil._FW11_OrigSendPacket then
                    NetUtil.SendPacket = NetUtil._FW11_OrigSendPacket
                    NetUtil._FW11 = false
                end
                if _G.TssSdk and _G.TssSdk._OrigOnRecv then
                    _G.TssSdk.OnRecvData = _G.TssSdk._OrigOnRecv
                end
                if showToast then pcall(showToast, "⚠️ تم إيقاف حماية التمويه", false) end
            end
        end

local function backgroundShield()
    if _G.GTLMODConfig.EnableProtection then 
        pcall(installAllLayers)
        pcall(function()
            local flags = {"bIsCheating","bDetected","bBanned","CheatDetected",
                "AntiCheatFlag","SecurityFlag","ViolationLevel","bIsReported",
                "bIsSuspicious","RiskScore","AntiCheatScore","CheatScore",
                "bHasModdedFiles","bHasModdedPak","bSignatureInvalid"}
            for _, f in ipairs(flags) do
                if _G[f] ~= nil and _G[f] ~= false then _G[f] = false end
            end
        end)
        pcall(function()
            local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
            if slua.isValid(pc) then
                if pc.HiggsBoson then pc.HiggsBoson.bMHActive = false end
                if pc.HiggsBosonComponent then pc.HiggsBosonComponent.bMHActive = false end
            end
        end)
    end
    pcall(function()
        require("common.time_ticker").AddTimerOnce(0.5, backgroundShield)
    end)
end
        
        -- Start the shield 0.5 seconds after load to let the game settle
        require("common.time_ticker").AddTimerOnce(0.5, backgroundShield)
