    -- CREATE BUTTON (Clean Hierarchy)
    -- ═══════════════════════════════════════════════════════════
    local SIZE = 76

    local function createButton() return true end

local function createButton_OLD()
    if UI.root and slua.isValid(UI.root) then
        pcall(function() UI.root:SetVisibility(0) end)
        return true
    end
    local canvas = getCanvas(); if not canvas then return false end

    local success = false
    pcall(function()
        -- 1. المربع الأساسي (الحجم 76x76)
        local box = CGame:NewObjectFromPath("/Script/UMG.SizeBox", canvas)
        if not box or not slua.isValid(box) then return end
        UI.root = box
UI.isCreated = true -- <--- أضف هذا السطر ليتمكن النظام من التعرف عليه
        pcall(function() box:SetWidthOverride(SIZE) end)
        pcall(function() box:SetHeightOverride(SIZE) end)

        -- 2. الزر (شفاف ليستقبل اللمس)
        local btn = CGame:NewObjectFromPath("/Script/UMG.Button", box)
        if not btn or not slua.isValid(btn) then return end
        pcall(function() btn:SetBackgroundColor(toL({R=0, G=0, B=0, A=0})) end)
        pcall(function() box:AddChild(btn) end)

        -- 3. الإطار الأخضر (يملأ الزر بالكامل)
        local frame = CGame:NewObjectFromPath("/Script/UMG.Border", btn)
        if not frame or not slua.isValid(frame) then return end
        UI.frame = frame
        pcall(function() frame:SetBrushColor(toL({R=0.2, G=1, B=0.5, A=1})) end) -- لون أخضر
        pcall(function() frame:SetPadding({Left=2, Top=2, Right=2, Bottom=2}) end) -- سماكة الإطار
        pcall(function() btn:AddChild(frame) end)

        -- 4. الخلفية الزرقاء الغامقة (جوا الإطار الأخضر)
        local bg = CGame:NewObjectFromPath("/Script/UMG.Border", frame)
        if not bg or not slua.isValid(bg) then return end
        UI.bg = bg
        pcall(function() bg:SetBrushColor(toL({R=0.02, G=0.03, B=0.08, A=1})) end) -- لون الخلفية
        pcall(function() frame:AddChild(bg) end)

        -- 5. النص (مفعل) جوا الخلفية الزرقاء مباشرة
        local lbl = CGame:NewObjectFromPath("/Script/UMG.TextBlock", bg)
        if not lbl or not slua.isValid(lbl) then return end
        UI.label = lbl
        pcall(function() lbl:SetText("مفعل") end)
        pcall(function()
            local f = lbl.Font; f.Size = 18
            pcall(function() f.TypefaceFontName = "Bold" end)
            lbl.Font = f
        end)
        pcall(function() lbl:SetColorAndOpacity(toS({R=1, G=1, B=1, A=1})) end) -- لون النص أبيض عشان يبان
        
        -- السر هنا: توسيط النص أفقياً وعمودياً
        pcall(function() lbl:SetJustification(1) end) 
        pcall(function() lbl:SetVerticalJustification(1) end) 
        
        pcall(function() bg:AddChild(lbl) end)

        -- 6. عند النقر (تشغيل / إيقاف)
pcall(function()
    btn.OnClicked:Add(function()
        if UI.dragMoved then
            UI.dragMoved = false
            return
        end
        -- عكس الحالة
        local newState = not _G.GTLMODConfig.EnableProtection
        _G.GTLMODConfig.EnableProtection = newState
        -- استدعاء دالة التفعيل/الإيقاف
        if _G.FW11_ToggleProtection then 
            _G.FW11_ToggleProtection(newState) 
        end
        showToast(newState and "تم تفعيل الحماية" or "تم إيقاف الحماية", newState)
    end)
end)

        -- 7. سحب الزر
        pcall(function()
            btn.OnPressed:Add(function()
                UI.dragging = true
                UI.dragMoved = false
                local tx, ty = getTouchPos()
                UI.lastTouchX = tx
                UI.lastTouchY = ty
            end)
        end)
        pcall(function()
            btn.OnReleased:Add(function()
                UI.dragging = false
            end)
        end)

        -- 8. إضافة الزر للشاشة
        local slot = canvas:AddChildToCanvas(box)
        if slot then
            UI.slot = slot
            pcall(function()
                slot:SetAutoSize(false)
                if FAnchors then
                    slot:SetAnchors(FAnchors(1.0, 0.0, 1.0, 0.0))
                    slot:SetAlignment(FVector2D(1.0, 0.0))
                    slot:SetPosition(FVector2D(UI.currentX, UI.currentY))
                end
                slot:SetSize(FVector2D(SIZE, SIZE))
                slot:SetZOrder(99998)
            end)
        end

        success = true
        log("الزر جاهز - يتحرك بلمس الشاشة")
    end)
    return success
end
    -- ═══════════════════════════════════════════════════════════
    -- DRAG POLLER (Mobile Touch)
    -- ═══════════════════════════════════════════════════════════
    local function pollDrag()
        if UI.dragging and UI.slot and slua.isValid(UI.slot) then
            pcall(function()
                local tx, ty = getTouchPos()
                if tx and ty and UI.lastTouchX and UI.lastTouchY then
                    local dx = tx - UI.lastTouchX
                    local dy = ty - UI.lastTouchY
                    if math.abs(dx) > 2 or math.abs(dy) > 2 then
                        UI.dragMoved = true
                        UI.currentX = UI.currentX + dx
                        UI.currentY = UI.currentY + dy
                        UI.slot:SetPosition(FVector2D(UI.currentX, UI.currentY))
                        UI.lastTouchX = tx
                        UI.lastTouchY = ty
                    end
                elseif tx and ty and not UI.lastTouchX then
                    UI.lastTouchX = tx
                    UI.lastTouchY = ty
                end
            end)
        end
        pcall(function()
            require("common.time_ticker").AddTimerOnce(0.02, pollDrag)
        end)
    end

    -- ═══════════════════════════════════════════════════════════
    -- PULSE ANIMATION
    -- ═══════════════════════════════════════════════════════════
    local function pulseLoop()
        if UI.frame and slua.isValid(UI.frame) then
            UI.pulse = UI.pulse + 0.08
            local a = 0.65 + 0.35 * math.abs(math.sin(UI.pulse))
            if UI.visuallyActive then
                pcall(function() UI.frame:SetBrushColor(toL({R=0.2*a, G=1.0*a, B=0.5*a, A=1})) end)
            else
                -- Inactive state pulses gold
                pcall(function() UI.frame:SetBrushColor(toL({R=0.85*a, G=0.65*a, B=0.20*a, A=1})) end)
            end
        end
        pcall(function()
            require("common.time_ticker").AddTimerOnce(0.06, pulseLoop)
        end)
    end

