    end)

    -- ═══════════════════════════════════════════════════════════
    -- 9. تزييف HiggsBoson (يخدع السيرفر بلا سكنات معدلة)
    -- ═══════════════════════════════════════════════════════════
    pcall(function()
        local Higgs = package.loaded["GameLua.Mod.BaseMod.Common.Security.HiggsBosonComponent"]
        if Higgs then
            Higgs.GetNetAvatarItemIDs = function() return {} end
            Higgs.GetCurWeaponSkinID = function() return 0 end
            Higgs.IsMHActive = function() return false end
            Higgs.CheckMHActive = function() return false end
            Higgs.bMHActive = false
            Higgs.bCallPreReplication = false
            if Higgs.BlackList then
                for k in pairs(Higgs.BlackList) do Higgs.BlackList[k] = nil end
            end
        end
        _G.BlackList = {}

        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
        if slua.isValid(pc) then
            if pc.HiggsBoson then
                pc.HiggsBoson.bMHActive = false
                pc.HiggsBoson.bCallPreReplication = false
                pcall(function() pc.HiggsBoson.ControlMHActive = function() end end)
            end
            if pc.HiggsBosonComponent then
                pc.HiggsBosonComponent.bMHActive = false
                pc.HiggsBosonComponent.bCallPreReplication = false
                pcall(function() pc.HiggsBosonComponent.ControlMHActive = function() end end)
            end
        end
    end)

    -- ═══════════════════════════════════════════════════════════
    -- 10. حجب تقارير فحص الملفات
    -- ═══════════════════════════════════════════════════════════
    pcall(function()
        if not NetUtil or not NetUtil.SendPacket or NetUtil._StealthPkt then return end
        local orig = NetUtil.SendPacket
        local blocked = {
            ["report_modded_files"] = true,
            ["report_pak_verify"] = true,
            ["report_file_integrity"] = true,
            ["report_md5_fail"] = true,
            ["on_tss_sdk_anti_data"] = true,
            ["tss_sdk_report"] = true,
            ["client_anti_cheat_report"] = true,
            ["report_signature_fail"] = true,
            ["report_apk_modified"] = true,
            ["report_build_prop"] = true,
            ["report_emulator"] = true,
            ["report_root"] = true,
            ["report_xposed"] = true,
            ["report_magisk"] = true,
            ["report_hook"] = true,
            ["report_debugger"] = true,
            ["report_memory_scan"] = true,
        }
        NetUtil.SendPacket = function(name, ...)
            if type(name) == "string" then
                if blocked[name] then return nil end
                local l = name:lower()
                if l:find("report") and (l:find("file") or l:find("md5") or l:find("hash") or l:find("signature") or l:find("modded")) then
                    return nil
                end
                if l:find("report") and (l:find("root") or l:find("emulator") or l:find("debug") or l:find("hook")) then
                    return nil
                end
            end
            return orig(name, ...)
        end
        NetUtil._StealthPkt = true
    end)

    -- ═══════════════════════════════════════════════════════════
    -- 11. تعطيل FileCheckSubsystem بالكامل
    -- ═══════════════════════════════════════════════════════════
    pcall(function()
        local SubMgr = package.loaded["GameLua.GameCore.Module.Subsystem.SubsystemMgr"]
        if SubMgr then
            local FC = SubMgr.Get and SubMgr:Get("FileCheckSubsystem")
            if FC then
                for k, v in pairs(FC) do
                    if type(v) == "function" and (
                        k:find("Check") or k:find("Scan") or k:find("Verify") or
                        k:find("Report") or k:find("Validate") or k:find("Start")
                    ) then
                        pcall(function() FC[k] = function() return true end end)
                    end
                end
            end
        end
    end)

    -- ═══════════════════════════════════════════════════════════
    -- 12. تزييف AvatarUtils (دوال فحص السكنات)
    -- ═══════════════════════════════════════════════════════════
    pcall(function()
        local AU = package.loaded["AvatarUtils"]
        if AU then
            AU.CheckIsWeaponInBlackList = function() return false end
            AU.IsValidAvatar = function() return true end
            AU.CheckAvatarIntegrity = function() return true end
            AU.ReportInvalidAvatar = function() end
            AU.VerifySkin = function() return true end
            AU.ValidateSkin = function() return true end
            AU.CheckWeapon = function() return true end
            AU.ValidateWeapon = function() return true end
        end
    end)

    -- ═══════════════════════════════════════════════════════════
    -- 13. مسح أي تعديلات مرئية في الذاكرة
    -- ═══════════════════════════════════════════════════════════
    pcall(function()
        -- منع كشف الملفات المعدلة عبر دوال الذاكرة
        if _G.MemoryScanner then
            _G.MemoryScanner.StartScan = function() end
            _G.MemoryScanner.GetResults = function() return {} end
            _G.MemoryScanner.CheckIntegrity = function() return true end
        end

        -- تنظيف أعلام الكشف
        local flags = {
            "bIsCheating", "bDetected", "bBanned", "CheatDetected",
            "AntiCheatFlag", "SecurityFlag", "ViolationLevel", "bIsReported",
            "bIsSuspicious", "RiskScore", "AntiCheatScore", "CheatScore",
            "bIsModded", "bIsModified", "bHasModdedFiles", "bHasModdedPak",
            "bHasXposed", "bHasRoot", "bHasMagisk", "bHasEmulator",
            "bHasDebugger", "bHasHook", "bSignatureInvalid", "bHashMismatch",
        }
        for _, f in ipairs(flags) do
            if _G[f] ~= nil then _G[f] = false end
        end
    end)

    -- ═══════════════════════════════════════════════════════════
    -- 14. حلقة حراسة (تعيد التطبيق كل ثانية)
    -- ═══════════════════════════════════════════════════════════
    local function guardLoop()
    -- التحقق من حالة الزر
    if not _G.GTLMODConfig.EnableProtection then
        pcall(function() require("common.time_ticker").AddTimerOnce(1.0, guardLoop) end)
        return
    end

    pcall(function()
        -- إعادة تزييف HiggsBoson
        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
            if slua.isValid(pc) then
                if pc.HiggsBoson then pc.HiggsBoson.bMHActive = false end
                if pc.HiggsBosonComponent then pc.HiggsBosonComponent.bMHActive = false end
            end

            -- تنظيف الأعلام
            local flags = {
                "bIsCheating", "bDetected", "bBanned", "CheatDetected",
                "bIsModded", "bHasModdedFiles", "bHasModdedPak",
                "bSignatureInvalid", "bHashMismatch",
            }
            for _, f in ipairs(flags) do
                if _G[f] ~= nil and _G[f] ~= false then _G[f] = false end
            end
        end)
        pcall(function()
            require("common.time_ticker").AddTimerOnce(1.0, guardLoop)
        end)
    end

    pcall(function()
        require("common.time_ticker").AddTimerOnce(1.0, guardLoop)
    end)

    log("v1.0 محمل — هوية رسمية Samsung Galaxy S21 Ultra")
    log("HWID: " .. FAKE.hwid)
    log("Model: " .. FAKE.model .. " | Brand: " .. FAKE.brand)
    log("IMEI: " .. FAKE.imei)
    log("تم تزييف: MD5, SHA, CRC, FileScan, ProcessScan, LibScan, Higgs")
end)
-- ============================================================================
-- ULTIMATE SMART CROSSHAIR (Neon Green / Target Lock Red) - Direct Draw Edition
-- ============================================================================
do
    local U = {}
    U.FLinearColor = import("LinearColor")
    U.FVector2D    = import("Vector2D")
    U.FAnchors     = rawget(_G, "FAnchors") or import("Anchors")
    U.FVector      = import("Vector")

    CyberCrosshair = {
        Canvas = nil,
        Dot = nil,
        DotSlot = nil,
        Lines = {},
        LineSlots = {},
        Diagonals = {},
        DiagSlots = {},
        LastColorState = -1,
        BaseOffset = 14,
        LineWidth = 2,
        LineLength = 8,
        DiagLength = 6,
    }

    local function GetCanvas()
        local canvas = nil
        pcall(function()
            local UIT = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
            if UIT and UIT.GetMainControlBaseUI then
                local UI = UIT.GetMainControlBaseUI()
                if UI and slua.isValid(UI) then
                    if UI.CanvasPanel_0 and slua.isValid(UI.CanvasPanel_0) then canvas = UI.CanvasPanel_0
                    elseif UI.CanvasPanel_42 and slua.isValid(UI.CanvasPanel_42) then canvas = UI.CanvasPanel_42 end
                end
            end
        end)
        return canvas
    end

    local function EnsureWidget()
        -- إذا كانت الواجهة موجودة وصالحة، لا نقم بإعادة إنشائها
        if CyberCrosshair.Canvas and slua.isValid(CyberCrosshair.Canvas) and 
           CyberCrosshair.Dot and slua.isValid(CyberCrosshair.Dot) then 
            return true 
        end
        
        -- تنظيف أي بقايا من واجهة قديمة
        pcall(function() if CyberCrosshair.Dot then CyberCrosshair.Dot:RemoveFromParent() end end)
        for i=1,4 do
            pcall(function() if CyberCrosshair.Lines[i] then CyberCrosshair.Lines[i]:RemoveFromParent() end end)
            pcall(function() if CyberCrosshair.Diagonals[i] then CyberCrosshair.Diagonals[i]:RemoveFromParent() end end)
        end
        
        CyberCrosshair.Lines = {}
        CyberCrosshair.LineSlots = {}
        CyberCrosshair.Diagonals = {}
        CyberCrosshair.DiagSlots = {}

        local canvas = GetCanvas()
        if not canvas then return false end
        CyberCrosshair.Canvas = canvas

        -- 1. النقطة المركزية (Dot)
        local Dot = nil
        pcall(function() Dot = CGame:NewObjectFromPath("/Script/UMG.Border", canvas) end)
        if Dot and slua.isValid(Dot) then
            pcall(function()
                Dot:SetBrushColor(U.FLinearColor(0, 1, 0, 1)) 
                Dot:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                local slot = canvas:AddChildToCanvas(Dot)
                if slot then
                    slot:SetAutoSize(false)
                    slot:SetSize(U.FVector2D(3, 3))
                    slot:SetAlignment(U.FVector2D(0.5, 0.5))
                    slot:SetPosition(U.FVector2D(0, 0))
                    slot:SetAnchors(U.FAnchors(0.5, 0.5, 0.5, 0.5))
                    slot:SetZOrder(9998)
                    CyberCrosshair.DotSlot = slot
                end
            end)
            CyberCrosshair.Dot = Dot
        end

        -- 2. الخطوط الأساسية
        for i = 1, 4 do
            local Line = nil
            pcall(function() Line = CGame:NewObjectFromPath("/Script/UMG.Border", canvas) end)
            if Line and slua.isValid(Line) then
                pcall(function()
                    Line:SetBrushColor(U.FLinearColor(0, 1, 0, 1))
                    Line:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                    local slot = canvas:AddChildToCanvas(Line)
                    if slot then
                        slot:SetAutoSize(false)
                        slot:SetAlignment(U.FVector2D(0.5, 0.5))
                        slot:SetAnchors(U.FAnchors(0.5, 0.5, 0.5, 0.5))
                        slot:SetPosition(U.FVector2D(0, 0))
                        slot:SetZOrder(9999)
                        if i <= 2 then 
                            slot:SetSize(U.FVector2D(CyberCrosshair.LineWidth, CyberCrosshair.LineLength))
                        else 
                            slot:SetSize(U.FVector2D(CyberCrosshair.LineLength, CyberCrosshair.LineWidth)) 
                        end
                        CyberCrosshair.LineSlots[i] = slot
                    end
                end)
                CyberCrosshair.Lines[i] = Line
            end
        end

        -- 3. الخطوط المائلة
        for i = 1, 4 do
            local Diag = nil
            pcall(function() Diag = CGame:NewObjectFromPath("/Script/UMG.Border", canvas) end)
            if Diag and slua.isValid(Diag) then
                pcall(function()
                    Diag:SetBrushColor(U.FLinearColor(0, 1, 0, 1))
                    Diag:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                    local slot = canvas:AddChildToCanvas(Diag)
                    if slot then
                        slot:SetAutoSize(false)
                        slot:SetAlignment(U.FVector2D(0.5, 0.5))
                        slot:SetAnchors(U.FAnchors(0.5, 0.5, 0.5, 0.5))
                        slot:SetPosition(U.FVector2D(0, 0))
                        slot:SetSize(U.FVector2D(CyberCrosshair.LineWidth, CyberCrosshair.DiagLength))
                        slot:SetZOrder(9999)
                        CyberCrosshair.DiagSlots[i] = slot
                    end
                end)
                CyberCrosshair.Diagonals[i] = Diag
            end
        end

        return true
    end

    local function IsEnemyInCrosshair(pc, localPlayer)
        local isTarget = false
        pcall(function()
            local ui_util = require("client.common.ui_util")
            local vp = ui_util and ui_util.GetViewportSize()
            if not vp then return end
            local centerX = vp.X * 0.5
            local centerY = vp.Y * 0.5

            local GameplayData = require("GameLua.GameCore.Data.GameplayData")
            local characters = GameplayData.GetAllPlayerCharacters()
            if not characters then return end

            for _, char in pairs(characters) do
                if slua.isValid(char) and char ~= localPlayer and char:IsAlive() and char.TeamID ~= localPlayer.TeamID then
                    local headPos = char:GetBonePos("head", U.FVector(0, 0, 0))
                    if headPos and (headPos.X ~= 0 or headPos.Y ~= 0) then
                        local screenPos = U.FVector2D()
                        if pc:ProjectWorldLocationToScreen(headPos, screenPos, false) then
                            local dx = screenPos.X - centerX
                            local dy = screenPos.Y - centerY
                            if math.sqrt(dx*dx + dy*dy) < 40 then
                                isTarget = true
                                break
                            end
                        end
                    end
                end
            end
        end)
        return isTarget
    end

    _G.Crosshair_ForceBuild = function()
    pcall(function() if CyberCrosshair.Dot then CyberCrosshair.Dot:RemoveFromParent() end end)
    for i=1,4 do
        pcall(function() if CyberCrosshair.Lines[i] then CyberCrosshair.Lines[i]:RemoveFromParent() end end)
        pcall(function() if CyberCrosshair.Diagonals[i] then CyberCrosshair.Diagonals[i]:RemoveFromParent() end end)
    end
    CyberCrosshair.Dot = nil
    CyberCrosshair.Lines = {}
    CyberCrosshair.LineSlots = {}
    CyberCrosshair.Diagonals = {}
    CyberCrosshair.DiagSlots = {}
    CyberCrosshair.Canvas = nil
end

local function UpdateCrosshair()
    if not _G.GTLMODConfig.EnableCrosshair then
        _G.Crosshair_ForceBuild()
        return
    end

    local success = EnsureWidget()
    if not success or not CyberCrosshair.Canvas or not slua.isValid(CyberCrosshair.Canvas) then return end

        local localPlayer = nil
        local pc = nil
        pcall(function()
            local GDP = require("GameLua.GameCore.Data.GameplayData")
            localPlayer = GDP.GetPlayerCharacter()
            pc = GDP.GetPlayerController()
        end)
        
        -- إذا لم نكن داخل اللعبة (في اللوبي مثلاً) لا نفعل شيء
        if not slua.isValid(localPlayer) or not slua.isValid(pc) then return end

        local isFiring = localPlayer.bIsWeaponFiring
        local isLocked = IsEnemyInCrosshair(pc, localPlayer)

        local state = 1
        if isLocked then state = 2 end

        if CyberCrosshair.LastColorState ~= state or isFiring then
            CyberCrosshair.LastColorState = state

            local r, g, b = 0.0, 1.0, 0.0 -- أخضر
            if state == 2 then r, g, b = 1.0, 0.0, 0.0 end -- أحمر

            local offset = CyberCrosshair.BaseOffset
            if isFiring then offset = offset + 6 end

            if CyberCrosshair.Dot and slua.isValid(CyberCrosshair.Dot) then
                pcall(function() CyberCrosshair.Dot:SetBrushColor(U.FLinearColor(r, g, b, 1.0)) end)
            end

            if CyberCrosshair.Lines[1] and slua.isValid(CyberCrosshair.Lines[1]) and CyberCrosshair.LineSlots[1] then
                pcall(function() 
                    CyberCrosshair.Lines[1]:SetBrushColor(U.FLinearColor(r,g,b,1))
                    CyberCrosshair.LineSlots[1]:SetPosition(U.FVector2D(0, -offset - (CyberCrosshair.LineLength/2))) 
                end)
            end
            if CyberCrosshair.Lines[2] and slua.isValid(CyberCrosshair.Lines[2]) and CyberCrosshair.LineSlots[2] then
                pcall(function() 
                    CyberCrosshair.Lines[2]:SetBrushColor(U.FLinearColor(r,g,b,1))
                    CyberCrosshair.LineSlots[2]:SetPosition(U.FVector2D(0, offset + (CyberCrosshair.LineLength/2))) 
                end)
            end
            if CyberCrosshair.Lines[3] and slua.isValid(CyberCrosshair.Lines[3]) and CyberCrosshair.LineSlots[3] then
                pcall(function() 
                    CyberCrosshair.Lines[3]:SetBrushColor(U.FLinearColor(r,g,b,1))
                    CyberCrosshair.LineSlots[3]:SetPosition(U.FVector2D(-offset - (CyberCrosshair.LineLength/2), 0)) 
                end)
            end
            if CyberCrosshair.Lines[4] and slua.isValid(CyberCrosshair.Lines[4]) and CyberCrosshair.LineSlots[4] then
                pcall(function() 
                    CyberCrosshair.Lines[4]:SetBrushColor(U.FLinearColor(r,g,b,1))
                    CyberCrosshair.LineSlots[4]:SetPosition(U.FVector2D(offset + (CyberCrosshair.LineLength/2), 0)) 
                end)
            end

            local diagOffset = offset * 0.8
            local diagAngles = {-45, 45, -135, 135}
            for i = 1, 4 do
                if CyberCrosshair.Diagonals[i] and slua.isValid(CyberCrosshair.Diagonals[i]) and CyberCrosshair.DiagSlots[i] then
                    pcall(function()
                        CyberCrosshair.Diagonals[i]:SetBrushColor(U.FLinearColor(r,g,b,1))
                        CyberCrosshair.Diagonals[i]:SetRenderAngle(diagAngles[i])
                        local angleRad = math.rad(diagAngles[i])
                        local px = math.cos(angleRad) * diagOffset
                        local py = math.sin(angleRad) * diagOffset
                        CyberCrosshair.DiagSlots[i]:SetPosition(U.FVector2D(px, py))
                    end)
                end
            end
        end
    end

    pcall(function()
        local ticker = require("common.time_ticker")
        if ticker and ticker.AddTimerLoop then
            -- تحديث سريع (30 إطار في الثانية) لضمان عدم حدوث تأخير
            ticker.AddTimerLoop(0, UpdateCrosshair, -1, 0.03)
        end
    end)
end

